public.billing_build_api_payload(uuid).definition:
CREATE OR REPLACE FUNCTION public.billing_build_api_payload(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_document jsonb;
BEGIN
    v_document := public.billing_fiscal_document_json(p_document_id);
    IF v_document IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN jsonb_build_object(
        'schema', 'rotero.billing.cfdi_api_payload.v1',
        'generated_at', now(),
        'document', v_document
    );
END;
$function$

public.billing_recalculate_document_tota.definition:
CREATE OR REPLACE FUNCTION public.billing_recalculate_document_totals(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_tenant_id uuid;
    v_subtotal numeric(14,2);
    v_discount numeric(14,2);
    v_transferred numeric(14,2);
    v_withheld numeric(14,2);
    v_total numeric(14,2);
BEGIN
    SELECT tenant_id INTO v_tenant_id
    FROM private.fiscal02_legacy_billing_documents
    WHERE id = p_document_id;

    IF v_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'document_not_found');
    END IF;

    UPDATE public.billing_document_lines
    SET subtotal = round(quantity * unit_price, 2),
        total = round(greatest((quantity * unit_price) - discount, 0), 2),
        updated_at = now()
    WHERE document_id = p_document_id;

    SELECT
        COALESCE(sum(subtotal), 0),
        COALESCE(sum(discount), 0)
    INTO v_subtotal, v_discount
    FROM public.billing_document_lines
    WHERE document_id = p_document_id;

    SELECT COALESCE(sum(amount), 0)
    INTO v_transferred
    FROM public.billing_document_taxes
    WHERE document_id = p_document_id
      AND tax_type = 'traslado';

    SELECT COALESCE(sum(amount), 0)
    INTO v_withheld
    FROM public.billing_document_taxes
    WHERE document_id = p_document_id
      AND tax_type = 'retencion';

    v_total := round(greatest(v_subtotal - v_discount + v_transferred - v_withheld, 0), 2);

    UPDATE public.billing_documents
    SET subtotal = v_subtotal,
        discount_total = v_discount,
        transferred_taxes_total = v_transferred,
        withheld_taxes_total = v_withheld,
        total = v_total,
        updated_at = now()
    WHERE id = p_document_id;

    RETURN jsonb_build_object(
        'success', true,
        'subtotal', v_subtotal,
        'discount_total', v_discount,
        'transferred_taxes_total', v_transferred,
        'withheld_taxes_total', v_withheld,
        'total', v_total
    );
END;
$function$

public.crm_generate_quote_reference(uuid.definition:
CREATE OR REPLACE FUNCTION public.crm_generate_quote_reference(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_reference text;
    v_attempts integer := 0;
BEGIN
    LOOP
        v_attempts := v_attempts + 1;
        v_reference := 'Q-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));

        EXIT WHEN NOT EXISTS (
            SELECT 1
            FROM public.crm_deals d
            WHERE d.tenant_id = p_tenant_id
              AND lower(d.quote_reference) = lower(v_reference)
        );

        IF v_attempts > 20 THEN
            RAISE EXCEPTION 'quote_reference_generation_failed';
        END IF;
    END LOOP;

    RETURN v_reference;
END;
$function$

public.fn_operations_infer_operation_sco.definition:
CREATE OR REPLACE FUNCTION public.fn_operations_infer_operation_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF COALESCE(NEW.origin_place->>'countryCode', 'MX') = 'US'
       OR COALESCE(NEW.destination_place->>'countryCode', 'MX') = 'US' THEN
        NEW.operation_scope := 'international';
    ELSIF NEW.operation_scope IS NULL OR NEW.operation_scope NOT IN ('national', 'international') THEN
        NEW.operation_scope := 'national';
    END IF;

    RETURN NEW;
END;
$function$

public.rpc_assign_operation(uuid, uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_assign_operation(p_tenant_id uuid, p_operation_id uuid, p_driver_id uuid, p_vehicle_id uuid, p_planned_departure timestamp with time zone, p_priority text DEFAULT 'normal'::text, p_driver_name text DEFAULT NULL::text, p_vehicle_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
        DECLARE v_tenant uuid;v_status text;
        BEGIN
          IF NOT public.tanda1_user_has_role(p_tenant_id,ARRAY['admin','operator']) THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
          SELECT tenant_id,status INTO v_tenant,v_status FROM public.operations WHERE id=p_operation_id FOR UPDATE;
          IF v_tenant IS NULL OR v_tenant<>p_tenant_id THEN RETURN jsonb_build_object('error','not_found_or_unauthorized'); END IF;
          IF v_status NOT IN ('draft','planned','assigned') THEN RETURN jsonb_build_object('error','invalid_status_for_assignment'); END IF;
          UPDATE public.operations SET driver_id=p_driver_id,vehicle_id=p_vehicle_id,driver_name=p_driver_name,vehicle_ref=p_vehicle_ref,
            planned_departure=p_planned_departure,priority=p_priority,status='assigned',assigned_at=now(),updated_at=now() WHERE id=p_operation_id;
          INSERT INTO public.audit_log(tenant_id,actor_user_id,action,entity_type,entity_id,metadata)
          VALUES(p_tenant_id,auth.uid(),'operation_assigned_legacy','operation',p_operation_id,jsonb_build_object('old_status',v_status));
          RETURN jsonb_build_object('success',true);
        EXCEPTION WHEN check_violation OR foreign_key_violation OR invalid_text_representation THEN RETURN jsonb_build_object('error','invalid_payload');
          WHEN OTHERS THEN RETURN jsonb_build_object('error','internal_error');
        END $function$

public.rpc_assign_operation_v2(uuid, uui.definition:
CREATE OR REPLACE FUNCTION public.rpc_assign_operation_v2(p_tenant_id uuid, p_operation_id uuid, p_driver_id uuid, p_driver_name text, p_vehicle_id uuid, p_vehicle_ref text, p_planned_departure timestamp with time zone, p_priority text DEFAULT 'normal'::text, p_reason text DEFAULT NULL::text, p_force_override boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_driver public.drivers%rowtype;
    v_vehicle public.vehicles%rowtype;
    v_role text;
    v_driver_occupied record;
    v_vehicle_occupied record;
    v_driver_changed boolean := false;
    v_vehicle_changed boolean := false;
    v_is_reassignment boolean := false;
BEGIN
    SELECT m.role
    INTO v_role
    FROM public.memberships m
    WHERE m.user_id = auth.uid()
      AND m.tenant_id = p_tenant_id;

    IF v_role NOT IN ('admin', 'operator') THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_force_override THEN
        IF v_role <> 'admin' THEN
            RETURN jsonb_build_object('error', 'unauthorized');
        END IF;

        IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
            RETURN jsonb_build_object('error', 'missing_override_reason');
        END IF;
    END IF;

    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id
      AND tenant_id = p_tenant_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF v_operation.status NOT IN ('planned', 'assigned', 'in_transit') THEN
        RETURN jsonb_build_object('error', 'invalid_status_for_assignment');
    END IF;

    SELECT *
    INTO v_driver
    FROM public.drivers
    WHERE id = p_driver_id
      AND tenant_id = p_tenant_id;

    IF v_driver.id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_driver');
    END IF;

    SELECT *
    INTO v_vehicle
    FROM public.vehicles
    WHERE id = p_vehicle_id
      AND tenant_id = p_tenant_id;

    IF v_vehicle.id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_vehicle');
    END IF;

    IF p_planned_departure IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_planned_departure');
    END IF;

    IF NOT p_force_override THEN
        IF v_driver.status <> 'available' OR v_driver.is_active = false THEN
            RETURN jsonb_build_object('error', 'driver_unavailable');
        END IF;

        IF v_vehicle.status <> 'available' OR v_vehicle.is_active = false THEN
            RETURN jsonb_build_object('error', 'vehicle_unavailable');
        END IF;
    END IF;

    SELECT *
    INTO v_driver_occupied
    FROM public.fn_driver_active_operation(p_tenant_id, p_driver_id, p_operation_id);

    SELECT *
    INTO v_vehicle_occupied
    FROM public.fn_vehicle_active_operation(p_tenant_id, p_vehicle_id, p_operation_id);

    IF NOT p_force_override THEN
        IF v_driver_occupied.operation_id IS NOT NULL THEN
            RETURN jsonb_build_object('error', 'driver_occupied');
        END IF;

        IF v_vehicle_occupied.operation_id IS NOT NULL THEN
            RETURN jsonb_build_object('error', 'vehicle_occupied');
        END IF;
    END IF;

    v_driver_changed := v_operation.driver_id IS DISTINCT FROM v_driver.id;
    v_vehicle_changed := v_operation.vehicle_id IS DISTINCT FROM v_vehicle.id;
    v_is_reassignment := (v_operation.driver_id IS NOT NULL OR v_operation.vehicle_id IS NOT NULL)
        AND (v_driver_changed OR v_vehicle_changed);

    IF v_is_reassignment AND NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_reassignment_reason');
    END IF;

    UPDATE public.operations
    SET driver_id = v_driver.id,
        vehicle_id = v_vehicle.id,
        driver_name = COALESCE(NULLIF(trim(p_driver_name), ''), v_driver.display_name),
        vehicle_ref = COALESCE(NULLIF(trim(p_vehicle_ref), ''), v_vehicle.display_name),
        planned_departure = p_planned_departure,
        priority = COALESCE(NULLIF(trim(p_priority), ''), 'normal'),
        status = CASE
            WHEN v_operation.status = 'planned' THEN 'assigned'
            ELSE v_operation.status
        END,
        assigned_at = CASE
            WHEN v_operation.status = 'planned' THEN now()
            ELSE v_operation.assigned_at
        END
    WHERE id = p_operation_id;

    IF (v_operation.driver_id IS NULL AND v_operation.vehicle_id IS NULL) OR v_is_reassignment THEN
        INSERT INTO public.operation_assignment_history (
            tenant_id,
            operation_id,
            change_type,
            old_driver_id,
            old_driver_name_snapshot,
            old_vehicle_id,
            old_vehicle_ref_snapshot,
            new_driver_id,
            new_driver_name_snapshot,
            new_vehicle_id,
            new_vehicle_ref_snapshot,
            reason,
            changed_by
        )
        VALUES (
            p_tenant_id,
            p_operation_id,
            CASE
                WHEN v_operation.driver_id IS NULL AND v_operation.vehicle_id IS NULL THEN 'initial_assignment'
                ELSE 'reassignment'
            END,
            v_operation.driver_id,
            v_operation.driver_name,
            v_operation.vehicle_id,
            v_operation.vehicle_ref,
            v_driver.id,
            COALESCE(NULLIF(trim(p_driver_name), ''), v_driver.display_name),
            v_vehicle.id,
            COALESCE(NULLIF(trim(p_vehicle_ref), ''), v_vehicle.display_name),
            NULLIF(trim(COALESCE(p_reason, '')), ''),
            auth.uid()
        );
    END IF;

    PERFORM public.rpc_write_audit(
        p_tenant_id,
        CASE
            WHEN v_is_reassignment THEN 'reassign_operation'
            ELSE 'assign_operation'
        END,
        'operation',
        p_operation_id,
        jsonb_build_object(
            'force_override', p_force_override,
            'reason', NULLIF(trim(COALESCE(p_reason, '')), ''),
            'previous_driver_id', v_operation.driver_id,
            'previous_vehicle_id', v_operation.vehicle_id,
            'new_driver_id', v_driver.id,
            'new_vehicle_id', v_vehicle.id,
            'driver_occupied_operation_id', v_driver_occupied.operation_id,
            'vehicle_occupied_operation_id', v_vehicle_occupied.operation_id
        )
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_calculate_payroll_period(uuid.definition:
CREATE OR REPLACE FUNCTION public.rpc_calculate_payroll_period(p_tenant_id uuid, p_period_id uuid, p_entries jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_period public.payroll_periods%rowtype;
    v_entry jsonb;
    v_employee public.payroll_employees%rowtype;
    v_entry_id uuid;
    v_days integer;
    v_absence_days numeric;
    v_absence_deduction numeric;
    v_loan_deduction numeric;
    v_discount_deduction numeric;
    v_manual_tax numeric;
    v_adjustment numeric;
    v_net numeric;
    v_loan_id uuid;
    v_entries jsonb := COALESCE(p_entries, '[]'::jsonb);
BEGIN
    IF NOT public.tanda3_user_has_role(p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    SELECT * INTO v_period
    FROM public.payroll_periods
    WHERE id = p_period_id AND tenant_id = p_tenant_id;

    IF v_period.id IS NULL THEN
        RETURN jsonb_build_object('error', 'period_not_found');
    END IF;
    IF v_period.status IN ('approved', 'paid', 'cancelled') THEN
        RETURN jsonb_build_object('error', 'period_locked');
    END IF;

    IF jsonb_array_length(v_entries) = 0 THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object('employee_id', id)), '[]'::jsonb)
        INTO v_entries
        FROM public.payroll_employees
        WHERE tenant_id = p_tenant_id AND is_active;
    END IF;

    DELETE FROM public.payroll_entry_items
    WHERE entry_id IN (SELECT id FROM public.payroll_entries WHERE period_id = p_period_id);
    DELETE FROM public.payroll_entries
    WHERE period_id = p_period_id;

    FOR v_entry IN SELECT * FROM jsonb_array_elements(v_entries)
    LOOP
        SELECT * INTO v_employee
        FROM public.payroll_employees
        WHERE id = (v_entry->>'employee_id')::uuid
          AND tenant_id = p_tenant_id
          AND is_active;

        IF v_employee.id IS NULL THEN
            CONTINUE;
        END IF;

        v_days := GREATEST((v_period.period_end - v_period.period_start + 1), 1);
        v_absence_days := COALESCE(NULLIF(v_entry->>'absence_days', '')::numeric, 0);
        v_absence_deduction := round((v_employee.base_salary / v_days) * v_absence_days, 2);
        v_loan_id := NULLIF(v_entry->>'loan_id', '')::uuid;

        IF v_loan_id IS NULL THEN
            SELECT id INTO v_loan_id
            FROM public.payroll_loans
            WHERE tenant_id = p_tenant_id
              AND employee_id = v_employee.id
              AND status = 'open'
              AND outstanding_balance > 0
            ORDER BY issued_at ASC, created_at ASC
            LIMIT 1;
        END IF;

        v_loan_deduction := COALESCE(NULLIF(v_entry->>'loan_deduction', '')::numeric, 0);
        IF v_loan_deduction = 0 AND v_loan_id IS NOT NULL THEN
            SELECT LEAST(suggested_period_deduction, outstanding_balance)
            INTO v_loan_deduction
            FROM public.payroll_loans
            WHERE id = v_loan_id
              AND tenant_id = p_tenant_id;
        END IF;

        v_discount_deduction := COALESCE(NULLIF(v_entry->>'discount_deduction', '')::numeric, 0);
        v_manual_tax := COALESCE(NULLIF(v_entry->>'manual_tax_amount', '')::numeric, 0);
        v_adjustment := COALESCE(NULLIF(v_entry->>'adjustment_amount', '')::numeric, 0);
        v_net := round(GREATEST(v_employee.base_salary - v_absence_deduction - v_loan_deduction - v_discount_deduction - v_manual_tax + v_adjustment, 0), 2);

        INSERT INTO public.payroll_entries (
            tenant_id, period_id, employee_id, salary_snapshot, salary_frequency_snapshot,
            days_in_period, absence_days, gross_amount, absence_deduction,
            loan_deduction, discount_deduction, manual_tax_amount, adjustment_amount,
            net_amount, notes
        )
        VALUES (
            p_tenant_id, p_period_id, v_employee.id, v_employee.base_salary, v_employee.salary_frequency,
            v_days, v_absence_days, v_employee.base_salary, v_absence_deduction,
            COALESCE(v_loan_deduction, 0), v_discount_deduction, v_manual_tax, v_adjustment,
            v_net, NULLIF(trim(COALESCE(v_entry->>'notes', '')), '')
        )
        RETURNING id INTO v_entry_id;

        INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount, quantity)
        VALUES (p_tenant_id, v_entry_id, 'base_salary', 'Sueldo base', v_employee.base_salary, 1);

        IF v_absence_deduction > 0 THEN
            INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount, quantity)
            VALUES (p_tenant_id, v_entry_id, 'absence', 'Faltas', v_absence_deduction, v_absence_days);
        END IF;
        IF COALESCE(v_loan_deduction, 0) > 0 THEN
            INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount, metadata)
            VALUES (p_tenant_id, v_entry_id, 'loan', 'Prestamo', v_loan_deduction, jsonb_build_object('loan_id', v_loan_id));
        END IF;
        IF v_discount_deduction > 0 THEN
            INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount)
            VALUES (p_tenant_id, v_entry_id, 'discount', 'Descuento', v_discount_deduction);
        END IF;
        IF v_manual_tax > 0 THEN
            INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount)
            VALUES (p_tenant_id, v_entry_id, 'manual_tax', 'Retencion manual', v_manual_tax);
        END IF;
        IF v_adjustment > 0 THEN
            INSERT INTO public.payroll_entry_items (tenant_id, entry_id, item_type, label, amount)
            VALUES (p_tenant_id, v_entry_id, 'adjustment', 'Ajuste manual', v_adjustment);
        END IF;
    END LOOP;

    UPDATE public.payroll_periods
    SET
        gross_total = COALESCE((SELECT sum(gross_amount) FROM public.payroll_entries WHERE period_id = p_period_id), 0),
        deductions_total = COALESCE((SELECT sum(absence_deduction + loan_deduction + discount_deduction) FROM public.payroll_entries WHERE period_id = p_period_id), 0),
        manual_tax_total = COALESCE((SELECT sum(manual_tax_amount) FROM public.payroll_entries WHERE period_id = p_period_id), 0),
        net_total = COALESCE((SELECT sum(net_amount) FROM public.payroll_entries WHERE period_id = p_period_id), 0),
        status = 'calculated',
        updated_at = now()
    WHERE id = p_period_id;

    RETURN jsonb_build_object('success', true, 'id', p_period_id);
END;
$function$

public.rpc_complete_operation_planning(u.definition:
CREATE OR REPLACE FUNCTION public.rpc_complete_operation_planning(p_operation_id uuid, p_service_type text, p_origin_place jsonb, p_destination_place jsonb, p_operational_window_start timestamp with time zone, p_operational_window_end timestamp with time zone, p_notes text DEFAULT NULL::text, p_cargo_summary jsonb DEFAULT NULL::jsonb, p_route_summary text DEFAULT NULL::text, p_destination_city text DEFAULT NULL::text, p_eta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_eta_display text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_route_summary text;
BEGIN
    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_operation.status NOT IN ('draft', 'planned') THEN
        RETURN jsonb_build_object('error', 'invalid_status_for_planning');
    END IF;

    IF NULLIF(trim(COALESCE(p_service_type, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_service_type');
    END IF;

    IF p_origin_place IS NULL OR p_destination_place IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_places');
    END IF;

    IF p_operational_window_start IS NULL OR p_operational_window_end IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_operational_window');
    END IF;

    IF p_operational_window_end < p_operational_window_start THEN
        RETURN jsonb_build_object('error', 'invalid_operational_window');
    END IF;

    IF p_cargo_summary IS NULL OR p_cargo_summary = '{}'::jsonb THEN
        RETURN jsonb_build_object('error', 'missing_cargo_summary');
    END IF;

    v_route_summary := COALESCE(
        NULLIF(trim(p_route_summary), ''),
        concat_ws(
            ' - ',
            NULLIF(trim(COALESCE(p_origin_place->>'municipality', '')), ''),
            NULLIF(trim(COALESCE(p_destination_place->>'municipality', '')), '')
        )
    );

    UPDATE public.operations
    SET service_type = trim(p_service_type),
        origin_place = p_origin_place,
        destination_place = p_destination_place,
        operational_window_start = p_operational_window_start,
        operational_window_end = p_operational_window_end,
        notes = p_notes,
        cargo_summary = p_cargo_summary,
        route_summary = NULLIF(trim(v_route_summary), ''),
        destination_city = COALESCE(NULLIF(trim(p_destination_city), ''), p_destination_place->>'municipality'),
        eta = p_eta,
        eta_display = p_eta_display,
        status = 'planned'
    WHERE id = p_operation_id;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_complete_operation_planning(p_operation_id uuid, p_service_type text, p_origin_place jsonb, p_destination_place jsonb, p_operational_window_start timestamp with time zone, p_operational_window_end timestamp with time zone, p_notes text DEFAULT NULL::text, p_cargo_summary jsonb DEFAULT NULL::jsonb, p_route_summary text DEFAULT NULL::text, p_destination_city text DEFAULT NULL::text, p_eta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_eta_display text DEFAULT NULL::text, p_operation_scope text DEFAULT 'national'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_route_summary text;
    v_scope text := COALESCE(NULLIF(trim(p_operation_scope), ''), 'national');
BEGIN
    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_operation.status NOT IN ('draft', 'planned') THEN
        RETURN jsonb_build_object('error', 'invalid_status_for_planning');
    END IF;

    IF v_scope NOT IN ('national', 'international') THEN
        RETURN jsonb_build_object('error', 'invalid_operation_scope');
    END IF;

    IF NULLIF(trim(COALESCE(p_service_type, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_service_type');
    END IF;

    IF p_origin_place IS NULL OR p_destination_place IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_places');
    END IF;

    IF NULLIF(trim(COALESCE(p_origin_place->>'countryCode', '')), '') IS NULL
       OR NULLIF(trim(COALESCE(p_origin_place->>'state', '')), '') IS NULL
       OR NULLIF(trim(COALESCE(p_origin_place->>'municipality', '')), '') IS NULL
       OR NULLIF(trim(COALESCE(p_destination_place->>'countryCode', '')), '') IS NULL
       OR NULLIF(trim(COALESCE(p_destination_place->>'state', '')), '') IS NULL
       OR NULLIF(trim(COALESCE(p_destination_place->>'municipality', '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'incomplete_places');
    END IF;

    IF v_scope = 'national'
       AND (p_origin_place->>'countryCode' <> 'MX' OR p_destination_place->>'countryCode' <> 'MX') THEN
        RETURN jsonb_build_object('error', 'invalid_national_country');
    END IF;

    IF p_operational_window_start IS NULL OR p_operational_window_end IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_operational_window');
    END IF;

    IF p_operational_window_end < p_operational_window_start THEN
        RETURN jsonb_build_object('error', 'invalid_operational_window');
    END IF;

    IF p_cargo_summary IS NULL OR p_cargo_summary = '{}'::jsonb THEN
        RETURN jsonb_build_object('error', 'missing_cargo_summary');
    END IF;

    v_route_summary := COALESCE(
        NULLIF(trim(p_route_summary), ''),
        concat_ws(
            ' -> ',
            NULLIF(trim(COALESCE(p_origin_place->>'label', '')), ''),
            NULLIF(trim(COALESCE(p_destination_place->>'label', '')), '')
        ),
        concat_ws(
            ' -> ',
            concat_ws(', ', NULLIF(trim(COALESCE(p_origin_place->>'municipality', '')), ''), NULLIF(trim(COALESCE(p_origin_place->>'state', '')), '')),
            concat_ws(', ', NULLIF(trim(COALESCE(p_destination_place->>'municipality', '')), ''), NULLIF(trim(COALESCE(p_destination_place->>'state', '')), ''))
        )
    );

    UPDATE public.operations
    SET operation_scope = v_scope,
        service_type = trim(p_service_type),
        origin_place = p_origin_place,
        destination_place = p_destination_place,
        operational_window_start = p_operational_window_start,
        operational_window_end = p_operational_window_end,
        notes = p_notes,
        cargo_summary = p_cargo_summary,
        route_summary = NULLIF(trim(v_route_summary), ''),
        destination_city = COALESCE(NULLIF(trim(p_destination_city), ''), p_destination_place->>'municipality'),
        eta = p_eta,
        eta_display = p_eta_display,
        status = 'planned',
        updated_at = now()
    WHERE id = p_operation_id;

    PERFORM public.rpc_write_audit(
        v_operation.tenant_id,
        'complete_operation_planning',
        'operation',
        p_operation_id,
        jsonb_build_object('operation_scope', v_scope, 'route_summary', v_route_summary)
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_create_credit_note(uuid, json.definition:
CREATE OR REPLACE FUNCTION public.rpc_create_credit_note(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_note_type text := COALESCE(NULLIF(p_payload->>'note_type', ''), 'customer_credit');
    v_status text := COALESCE(NULLIF(p_payload->>'status', ''), 'applied');
    v_currency text := COALESCE(NULLIF(upper(trim(p_payload->>'currency')), ''), 'MXN');
    v_subtotal numeric := COALESCE(NULLIF(p_payload->>'subtotal', '')::numeric, 0);
    v_iva numeric := COALESCE(NULLIF(p_payload->>'iva', '')::numeric, 0);
    v_total numeric;
    v_exchange_rate numeric := NULLIF(p_payload->>'exchange_rate', '')::numeric;
    v_exchange_rate_date date := NULLIF(p_payload->>'exchange_rate_date', '')::date;
    v_finance_invoice public.finance_invoices%rowtype;
    v_finance_invoice_id uuid := NULLIF(p_payload->>'finance_invoice_id', '')::uuid;
    v_customer_id uuid := NULLIF(p_payload->>'customer_id', '')::uuid;
    v_provider_id uuid := NULLIF(p_payload->>'provider_id', '')::uuid;
    v_operation_id uuid := NULLIF(p_payload->>'operation_id', '')::uuid;
    v_cfdi_id uuid := NULLIF(p_payload->>'cfdi_id', '')::uuid;
    v_source_billing_document_id uuid := NULLIF(p_payload->>'source_billing_document_id', '')::uuid;
BEGIN
    IF NOT public.tanda2_user_has_role(p_tenant_id, ARRAY['admin', 'finance']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    v_total := COALESCE(NULLIF(p_payload->>'total', '')::numeric, v_subtotal + v_iva);

    IF v_note_type NOT IN ('customer_credit', 'provider_credit') THEN
        RETURN jsonb_build_object('error', 'invalid_note_type');
    END IF;

    IF v_status NOT IN ('draft', 'applied', 'cancelled') THEN
        RETURN jsonb_build_object('error', 'invalid_status');
    END IF;

    IF v_currency NOT IN ('MXN', 'USD') THEN
        RETURN jsonb_build_object('error', 'invalid_currency');
    END IF;

    IF v_total < 0 THEN
        RETURN jsonb_build_object('error', 'invalid_total');
    END IF;

    IF v_finance_invoice_id IS NOT NULL THEN
        SELECT *
        INTO v_finance_invoice
        FROM private.fiscal02_legacy_finance_invoices
        WHERE id = v_finance_invoice_id
          AND tenant_id = p_tenant_id;

        IF v_finance_invoice.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invoice_not_found');
        END IF;

        v_customer_id := COALESCE(v_customer_id, v_finance_invoice.customer_id);
        v_provider_id := COALESCE(v_provider_id, v_finance_invoice.provider_id);
        v_operation_id := COALESCE(v_operation_id, v_finance_invoice.operation_id);
        v_cfdi_id := COALESCE(v_cfdi_id, v_finance_invoice.linked_cfdi_id);
        v_source_billing_document_id := COALESCE(v_source_billing_document_id, v_finance_invoice.billing_document_id);
        v_currency := COALESCE(NULLIF(upper(trim(p_payload->>'currency')), ''), v_finance_invoice.currency, 'MXN');
        v_exchange_rate := COALESCE(v_exchange_rate, v_finance_invoice.exchange_rate);
        v_exchange_rate_date := COALESCE(v_exchange_rate_date, v_finance_invoice.exchange_rate_date);
    END IF;

    IF v_note_type = 'customer_credit' AND v_customer_id IS NULL AND v_cfdi_id IS NULL AND v_finance_invoice_id IS NULL THEN
        RETURN jsonb_build_object('error', 'customer_credit_requires_invoice_or_customer');
    END IF;

    IF v_note_type = 'provider_credit' AND v_provider_id IS NULL AND v_finance_invoice_id IS NULL THEN
        RETURN jsonb_build_object('error', 'provider_credit_requires_provider_or_ap_invoice');
    END IF;

    IF v_customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE c.id = v_customer_id AND c.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'invalid_customer');
    END IF;

    IF v_provider_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.logistics_providers p WHERE p.id = v_provider_id AND p.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'invalid_provider');
    END IF;

    IF v_operation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.operations o WHERE o.id = v_operation_id AND o.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'invalid_operation');
    END IF;

    IF v_cfdi_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM private.fiscal02_readable_cfdis c WHERE c.id = v_cfdi_id AND c.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'invalid_cfdi');
    END IF;

    IF v_source_billing_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM private.fiscal02_legacy_billing_documents d WHERE d.id = v_source_billing_document_id AND d.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'invalid_billing_document');
    END IF;

    IF v_currency = 'MXN' THEN
        v_exchange_rate := 1;
        v_exchange_rate_date := COALESCE(v_exchange_rate_date, COALESCE(NULLIF(p_payload->>'issue_date', '')::date, current_date));
    ELSIF v_exchange_rate IS NULL OR v_exchange_rate <= 0 OR v_exchange_rate_date IS NULL THEN
        RETURN jsonb_build_object('error', 'exchange_rate_required_for_usd');
    END IF;

    INSERT INTO public.billing_credit_notes (
        tenant_id,
        note_type,
        customer_id,
        provider_id,
        operation_id,
        finance_invoice_id,
        cfdi_id,
        source_billing_document_id,
        folio,
        provider_note_reference,
        issue_date,
        received_at,
        reason,
        subtotal,
        iva,
        total,
        currency,
        exchange_rate,
        exchange_rate_date,
        total_mxn,
        status,
        notes,
        created_by
    ) VALUES (
        p_tenant_id,
        v_note_type,
        v_customer_id,
        v_provider_id,
        v_operation_id,
        v_finance_invoice_id,
        v_cfdi_id,
        v_source_billing_document_id,
        NULLIF(trim(COALESCE(p_payload->>'folio', '')), ''),
        NULLIF(trim(COALESCE(p_payload->>'provider_note_reference', '')), ''),
        COALESCE(NULLIF(p_payload->>'issue_date', '')::date, current_date),
        NULLIF(p_payload->>'received_at', '')::timestamptz,
        NULLIF(trim(COALESCE(p_payload->>'reason', '')), ''),
        v_subtotal,
        v_iva,
        v_total,
        v_currency,
        v_exchange_rate,
        v_exchange_rate_date,
        public.tanda2_amount_mxn(v_total, v_currency, v_exchange_rate),
        v_status,
        NULLIF(trim(COALESCE(p_payload->>'notes', '')), ''),
        auth.uid()
    ) RETURNING id INTO v_id;

    IF v_finance_invoice_id IS NOT NULL AND v_status = 'applied' THEN
        PERFORM public.rpc_update_finance_invoice_status(
            p_tenant_id,
            v_finance_invoice_id,
            CASE
                WHEN (
                    SELECT COALESCE(SUM(fp.amount), 0)
                    FROM private.fiscal02_legacy_finance_payments fp
                    WHERE fp.invoice_id = v_finance_invoice_id
                ) + (
                    SELECT COALESCE(SUM(cn.total), 0)
                    FROM private.fiscal02_legacy_billing_credit_notes cn
                    WHERE cn.finance_invoice_id = v_finance_invoice_id
                      AND cn.status = 'applied'
                ) >= COALESCE(v_finance_invoice.amount, v_total)
                THEN 'paid'
                ELSE COALESCE(NULLIF(v_finance_invoice.status, ''), 'open')
            END
        );
    END IF;

    RETURN jsonb_build_object('success', true, 'id', v_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_create_customer(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_create_customer(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_display_name text := trim(COALESCE(p_payload->>'display_name', ''));
    v_tax_id text := NULLIF(upper(trim(COALESCE(p_payload->>'tax_id', ''))), '');
    v_confirm_duplicate boolean := COALESCE((p_payload->>'confirm_duplicate')::boolean, false);
    v_probable_duplicates jsonb := '[]'::jsonb;
    v_new_id uuid;
    v_is_active boolean := COALESCE((p_payload->>'is_active')::boolean, true);
    v_preferred_currency text := COALESCE(NULLIF(upper(trim(COALESCE(p_payload->>'preferred_currency', ''))), ''), 'MXN');
BEGIN
    IF NOT public.tanda1_user_has_role(p_tenant_id, ARRAY['admin', 'operator']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_preferred_currency NOT IN ('MXN', 'USD') THEN
        RETURN jsonb_build_object('error', 'invalid_preferred_currency');
    END IF;

    IF NOT public.customer_display_name_is_valid(v_display_name) THEN
        RETURN jsonb_build_object('error', 'invalid_display_name');
    END IF;

    IF v_tax_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.customers c
        WHERE c.tenant_id = p_tenant_id
          AND lower(btrim(c.tax_id)) = lower(v_tax_id)
    ) THEN
        RETURN jsonb_build_object('error', 'tax_id_exists');
    END IF;

    v_probable_duplicates := public.customer_probable_duplicates_json(p_tenant_id, v_display_name);
    IF NOT v_confirm_duplicate AND jsonb_array_length(v_probable_duplicates) > 0 THEN
        RETURN jsonb_build_object(
            'error', 'probable_duplicate_display_name',
            'probable_duplicates', v_probable_duplicates
        );
    END IF;

    INSERT INTO public.customers (
        tenant_id,
        display_name,
        legal_name,
        primary_contact_name,
        primary_contact_email,
        primary_contact_phone,
        tax_id,
        billing_email,
        preferred_currency,
        notes,
        is_active,
        created_at,
        updated_at
    ) VALUES (
        p_tenant_id,
        v_display_name,
        NULLIF(trim(COALESCE(p_payload->>'legal_name', '')), ''),
        NULLIF(trim(COALESCE(p_payload->>'primary_contact_name', '')), ''),
        NULLIF(trim(COALESCE(p_payload->>'primary_contact_email', '')), ''),
        NULLIF(trim(COALESCE(p_payload->>'primary_contact_phone', '')), ''),
        v_tax_id,
        NULLIF(trim(COALESCE(p_payload->>'billing_email', '')), ''),
        v_preferred_currency,
        NULLIF(trim(COALESCE(p_payload->>'notes', '')), ''),
        v_is_active,
        now(),
        now()
    )
    RETURNING id INTO v_new_id;

    PERFORM public.rpc_write_audit(
        p_tenant_id,
        'create_customer',
        'customer',
        v_new_id,
        jsonb_build_object('display_name', v_display_name, 'is_active', v_is_active, 'preferred_currency', v_preferred_currency)
    );

    RETURN jsonb_build_object('success', true, 'id', v_new_id);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'tax_id_exists');
END;
$function$

public.rpc_create_inventory_lot(uuid, te.definition:
CREATE OR REPLACE FUNCTION public.rpc_create_inventory_lot(p_tenant_id uuid, p_sku text, p_lot_code text, p_qty_on_hand numeric, p_warehouse text DEFAULT NULL::text, p_received_at timestamp with time zone DEFAULT now(), p_unit_cost numeric DEFAULT NULL::numeric, p_currency text DEFAULT 'MXN'::text, p_pedimento_ref text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
