public.rpc_create_operation_billing(uuid.definition:
CREATE OR REPLACE FUNCTION public.rpc_create_operation_billing(p_operation_id uuid, p_billing_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_summary jsonb;
    v_new_id uuid;
BEGIN
    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.operation_billing b
        WHERE b.operation_id = p_operation_id
    ) THEN
        RETURN jsonb_build_object('error', 'billing_record_exists');
    END IF;

    v_summary := public.rpc_get_operation_billing_summary(p_operation_id);
    IF NOT COALESCE((v_summary->>'is_billing_ready')::boolean, false) THEN
        RETURN jsonb_build_object(
            'error', 'billing_not_ready',
            'billing_blockers', COALESCE(v_summary->'billing_blockers', '[]'::jsonb)
        );
    END IF;

    INSERT INTO public.operation_billing (
        tenant_id,
        operation_id,
        status,
        billing_reference,
        notes,
        created_at,
        updated_at
    ) VALUES (
        v_operation.tenant_id,
        p_operation_id,
        'draft',
        NULLIF(trim(COALESCE(p_billing_reference, '')), ''),
        NULLIF(trim(COALESCE(p_notes, '')), ''),
        now(),
        now()
    )
    RETURNING id INTO v_new_id;

    PERFORM public.rpc_write_audit(
        v_operation.tenant_id,
        'create_operation_billing',
        'operation_billing',
        v_new_id,
        jsonb_build_object(
            'operation_id', p_operation_id,
            'billing_reference', NULLIF(trim(COALESCE(p_billing_reference, '')), '')
        )
    );

    RETURN jsonb_build_object('success', true, 'id', v_new_id);
END;
$function$

public.rpc_create_operation_draft(uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_create_operation_draft(p_tenant_id uuid, p_reference_code text, p_client_display_name text, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new_id uuid;
    v_customer public.customers%rowtype;
    v_client_display_name text := NULLIF(trim(COALESCE(p_client_display_name, '')), '');
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = p_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF NULLIF(trim(COALESCE(p_reference_code, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_reference_code');
    END IF;

    IF p_customer_id IS NOT NULL THEN
        SELECT *
        INTO v_customer
        FROM public.customers
        WHERE id = p_customer_id
          AND tenant_id = p_tenant_id;

        IF v_customer.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_customer');
        END IF;

        IF v_customer.is_active = false THEN
            RETURN jsonb_build_object('error', 'customer_inactive');
        END IF;

        v_client_display_name := COALESCE(v_client_display_name, v_customer.display_name);
    END IF;

    IF v_client_display_name IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_client');
    END IF;

    INSERT INTO public.operations (
        tenant_id,
        reference_code,
        client_display_name,
        customer_id,
        status
    ) VALUES (
        p_tenant_id,
        trim(p_reference_code),
        v_client_display_name,
        p_customer_id,
        'draft'
    )
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object('success', true, 'id', v_new_id);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'reference_exists');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_create_operation_draft(p_tenant_id uuid, p_reference_code text, p_client_display_name text, p_customer_id uuid DEFAULT NULL::uuid, p_operation_scope text DEFAULT 'national'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new_id uuid;
    v_customer public.customers%rowtype;
    v_scope text := COALESCE(NULLIF(trim(p_operation_scope), ''), 'national');
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = p_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_scope NOT IN ('national', 'international') THEN
        RETURN jsonb_build_object('error', 'invalid_operation_scope');
    END IF;

    IF NULLIF(trim(COALESCE(p_reference_code, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_reference_code');
    END IF;

    IF NULLIF(trim(COALESCE(p_client_display_name, '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_client');
    END IF;

    IF p_customer_id IS NOT NULL THEN
        SELECT *
        INTO v_customer
        FROM public.customers
        WHERE id = p_customer_id
          AND tenant_id = p_tenant_id;

        IF v_customer.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_customer');
        END IF;

        IF v_customer.is_active = false THEN
            RETURN jsonb_build_object('error', 'customer_inactive');
        END IF;
    END IF;

    INSERT INTO public.operations (
        tenant_id,
        reference_code,
        client_display_name,
        customer_id,
        operation_scope,
        status
    ) VALUES (
        p_tenant_id,
        trim(p_reference_code),
        COALESCE(v_customer.display_name, trim(p_client_display_name)),
        p_customer_id,
        v_scope,
        'draft'
    )
    RETURNING id INTO v_new_id;

    PERFORM public.rpc_write_audit(
        p_tenant_id,
        'create_operation_draft',
        'operation',
        v_new_id,
        jsonb_build_object('reference_code', trim(p_reference_code), 'operation_scope', v_scope)
    );

    RETURN jsonb_build_object('success', true, 'id', v_new_id);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'reference_exists');
END;
$function$

