CREATE OR REPLACE FUNCTION public.rpc_mark_operation_billing_issued(p_operation_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_billing public.operation_billing%rowtype;
    v_summary jsonb;
BEGIN
    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    SELECT *
    INTO v_billing
    FROM public.operation_billing
    WHERE operation_id = p_operation_id;

    IF v_billing.id IS NULL THEN
        RETURN jsonb_build_object('error', 'billing_record_missing');
    END IF;

    IF v_billing.status <> 'draft' THEN
        RETURN jsonb_build_object('error', 'invalid_billing_status');
    END IF;

    v_summary := public.rpc_get_operation_billing_summary(p_operation_id);
    IF NOT COALESCE((v_summary->>'is_billing_ready')::boolean, false) THEN
        RETURN jsonb_build_object(
            'error', 'billing_not_ready',
            'billing_blockers', COALESCE(v_summary->'billing_blockers', '[]'::jsonb)
        );
    END IF;

    UPDATE public.operation_billing
    SET status = 'issued',
        issued_at = now(),
        issued_by = auth.uid(),
        notes = COALESCE(NULLIF(trim(COALESCE(p_notes, '')), ''), notes),
        updated_at = now()
    WHERE id = v_billing.id;

    PERFORM public.rpc_write_audit(
        v_operation.tenant_id,
        'issue_operation_billing',
        'operation_billing',
        v_billing.id,
        jsonb_build_object('operation_id', p_operation_id)
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_move_deal(uuid, text, timesta.definition:
CREATE OR REPLACE FUNCTION public.rpc_move_deal(p_deal_id uuid, p_new_stage text, p_client_timestamp timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_deal public.crm_deals%rowtype;
BEGIN
    SELECT *
    INTO v_deal
    FROM public.crm_deals
    WHERE id = p_deal_id;

    IF v_deal.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_deal.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_new_stage NOT IN ('lead', 'qualified', 'proposal', 'won', 'lost') THEN
        RETURN jsonb_build_object('error', 'invalid_stage');
    END IF;

    IF v_deal.quote_status = 'converted' AND p_new_stage <> 'won' THEN
        RETURN jsonb_build_object('error', 'converted_quote_locked');
    END IF;

    IF v_deal.quote_status = 'approved' AND p_new_stage <> 'proposal' THEN
        RETURN jsonb_build_object('error', 'approved_quote_must_stay_in_proposal');
    END IF;

    IF p_new_stage = 'won' AND v_deal.quote_status <> 'converted' THEN
        RETURN jsonb_build_object('error', 'convert_quote_before_won');
    END IF;

    IF p_new_stage = 'lost' AND v_deal.quote_status <> 'converted' THEN
        UPDATE public.crm_deals
        SET stage = 'lost',
            quote_status = 'rejected',
            rejected_at = COALESCE(rejected_at, now()),
            rejected_by = COALESCE(rejected_by, auth.uid()),
            rejection_note = COALESCE(rejection_note, 'Marked lost from pipeline'),
            last_touch_at = COALESCE(p_client_timestamp, now()),
            updated_at = now()
        WHERE id = p_deal_id;
    ELSE
        UPDATE public.crm_deals
        SET stage = p_new_stage,
            last_touch_at = COALESCE(p_client_timestamp, now()),
            updated_at = now()
        WHERE id = p_deal_id;
    END IF;

    PERFORM public.rpc_seed_checklist_for_deal(p_deal_id);

    PERFORM public.rpc_write_audit(
        v_deal.tenant_id,
        'move_deal_stage',
        'deal',
        p_deal_id,
        jsonb_build_object('old_stage', v_deal.stage, 'new_stage', p_new_stage, 'quote_status', v_deal.quote_status)
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_queue_billing_document_for_ap.definition:
CREATE OR REPLACE FUNCTION public.rpc_queue_billing_document_for_api(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_document public.billing_documents%rowtype;
    v_validation jsonb;
    v_existing public.billing_api_outbox%rowtype;
    v_outbox_id uuid;
    v_payload jsonb;
    v_provider_key text;
BEGIN
    SELECT *
    INTO v_document
    FROM private.fiscal02_legacy_billing_documents
    WHERE id = p_document_id;

    IF v_document.id IS NULL THEN
        RETURN jsonb_build_object('error', 'document_not_found');
    END IF;

    IF NOT public.billing_user_has_tenant(v_document.tenant_id, ARRAY['admin', 'operator']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_document.status IN ('queued', 'stamped', 'cancelled', 'voided') THEN
        RETURN jsonb_build_object('error', 'document_locked');
    END IF;

    v_validation := public.rpc_validate_billing_document_for_api(p_document_id);

    IF jsonb_array_length(COALESCE(v_validation->'blockers', '[]'::jsonb)) > 0 THEN
        RETURN jsonb_build_object(
            'error', 'validation_blocked',
            'blockers', v_validation->'blockers',
            'warnings', v_validation->'warnings'
        );
    END IF;

    SELECT *
    INTO v_existing
    FROM public.billing_api_outbox
    WHERE document_id = p_document_id
      AND status IN ('queued', 'sending')
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'reused_existing', true,
            'outbox_id', v_existing.id,
            'document', public.billing_fiscal_document_json(p_document_id)
        );
    END IF;

    v_payload := public.billing_build_api_payload(p_document_id);

    SELECT fp.api_provider_key
    INTO v_provider_key
    FROM public.billing_fiscal_profiles fp
    WHERE fp.tenant_id = v_document.tenant_id;

    INSERT INTO public.billing_api_outbox (
        tenant_id,
        document_id,
        provider_key,
        status,
        idempotency_key,
        request_payload,
        next_attempt_at
    ) VALUES (
        v_document.tenant_id,
        p_document_id,
        v_provider_key,
        'queued',
        p_document_id::text || ':' || gen_random_uuid()::text,
        v_payload,
        now()
    )
    RETURNING id INTO v_outbox_id;

    UPDATE public.billing_documents
    SET status = 'queued',
        queued_at = now(),
        api_payload = v_payload,
        updated_at = now()
    WHERE id = p_document_id;

    RETURN jsonb_build_object(
        'success', true,
        'reused_existing', false,
        'outbox_id', v_outbox_id,
        'document', public.billing_fiscal_document_json(p_document_id)
    );
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'active_outbox_already_exists');
WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

