public.rpc_resolve_daily_work_item(uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_resolve_daily_work_item(p_item_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing public.daily_work_items%rowtype;
    v_status text := COALESCE(NULLIF(trim(COALESCE(p_status, '')), ''), 'resolved');
    v_item public.daily_work_items%rowtype;
BEGIN
    IF v_status NOT IN ('open', 'in_progress', 'resolved', 'dismissed') THEN
        RETURN jsonb_build_object('error', 'invalid_status');
    END IF;

    SELECT * INTO v_existing
    FROM public.daily_work_items
    WHERE id = p_item_id;

    IF v_existing.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT public.tanda6_can_mutate_area(v_existing.tenant_id, v_existing.area) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    UPDATE public.daily_work_items
    SET
        status = v_status,
        resolved_at = CASE WHEN v_status IN ('resolved', 'dismissed') THEN now() ELSE NULL END,
        resolved_by = CASE WHEN v_status IN ('resolved', 'dismissed') THEN auth.uid() ELSE NULL END,
        metadata = metadata || jsonb_build_object(
            'last_status_note', NULLIF(trim(COALESCE(p_note, '')), ''),
            'last_status_at', now(),
            'last_status_by', auth.uid()
        )
    WHERE id = p_item_id
    RETURNING * INTO v_item;

    RETURN to_jsonb(v_item);
END;
$function$

public.rpc_revoke_operation_tokens(uuid).definition:
CREATE OR REPLACE FUNCTION public.rpc_revoke_operation_tokens(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor uuid := auth.uid();
    v_operation record;
    v_revoked_count integer := 0;
    v_revoked_driver boolean := false;
    v_revoked_public boolean := false;
    v_revoked_at timestamptz := now();
BEGIN
    IF v_actor IS NULL THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    SELECT o.id, o.tenant_id
    INTO v_operation
    FROM operations o
    WHERE o.id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM memberships m
        WHERE m.user_id = v_actor
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    WITH revoked AS (
        UPDATE tracking_tokens t
        SET state = 'revoked',
            revoked_at = v_revoked_at,
            revoked_by = v_actor
        WHERE t.operation_id = p_operation_id
          AND t.scope IN ('driver:write', 'public:read')
          AND t.state IN ('active', 'soft_expired')
        RETURNING t.scope
    )
    SELECT
        count(*),
        bool_or(scope = 'driver:write'),
        bool_or(scope = 'public:read')
    INTO
        v_revoked_count,
        v_revoked_driver,
        v_revoked_public
    FROM revoked;

    RETURN jsonb_build_object(
        'success', true,
        'revoked_count', COALESCE(v_revoked_count, 0),
        'revoked_driver', COALESCE(v_revoked_driver, false),
        'revoked_public', COALESCE(v_revoked_public, false),
        'revoked_at', to_char(v_revoked_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
END;
$function$

