$function$

public.rpc_set_driver_status(uuid, text,.definition:
CREATE OR REPLACE FUNCTION public.rpc_set_driver_status(p_driver_id uuid, p_status text, p_reason text DEFAULT NULL::text, p_force_override boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_driver public.drivers%rowtype;
    v_role text;
    v_occupied record;
BEGIN
    SELECT *
    INTO v_driver
    FROM public.drivers
    WHERE id = p_driver_id;

    IF v_driver.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    SELECT m.role
    INTO v_role
    FROM public.memberships m
    WHERE m.user_id = auth.uid()
      AND m.tenant_id = v_driver.tenant_id;

    IF v_role NOT IN ('admin', 'operator') THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_status NOT IN ('available', 'unavailable', 'inactive') THEN
        RETURN jsonb_build_object('error', 'invalid_status');
    END IF;

    IF p_status = 'inactive' AND v_role <> 'admin' THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    SELECT *
    INTO v_occupied
    FROM public.fn_driver_active_operation(v_driver.tenant_id, p_driver_id, NULL);

    IF v_occupied.operation_id IS NOT NULL
       AND p_status IN ('unavailable', 'inactive')
       AND NOT p_force_override THEN
        RETURN jsonb_build_object('error', 'resource_occupied');
    END IF;

    IF p_force_override THEN
        IF v_role <> 'admin' THEN
            RETURN jsonb_build_object('error', 'unauthorized');
        END IF;

        IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
            RETURN jsonb_build_object('error', 'missing_override_reason');
        END IF;
    END IF;

    UPDATE public.drivers
    SET status = p_status,
        is_active = (p_status <> 'inactive'),
        availability_note = CASE
            WHEN p_status = 'available' THEN NULL
            WHEN NULLIF(trim(COALESCE(p_reason, '')), '') IS NOT NULL THEN trim(p_reason)
            ELSE availability_note
        END,
        last_status_changed_at = now(),
        last_status_changed_by = auth.uid()
    WHERE id = p_driver_id;

    PERFORM public.rpc_write_audit(
        v_driver.tenant_id,
        CASE WHEN p_force_override THEN 'override_driver_status' ELSE 'set_driver_status' END,
        'driver',
        p_driver_id,
        jsonb_build_object(
            'previous_status', v_driver.status,
            'new_status', p_status,
            'reason', NULLIF(trim(COALESCE(p_reason, '')), ''),
            'force_override', p_force_override,
            'occupied_operation_id', v_occupied.operation_id
        )
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

