public.rpc_update_customer(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_update_customer(p_customer_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_customer public.customers%rowtype;
    v_display_name text;
    v_tax_id text;
    v_confirm_duplicate boolean := COALESCE((p_patch->>'confirm_duplicate')::boolean, false);
    v_probable_duplicates jsonb := '[]'::jsonb;
    v_preferred_currency text;
BEGIN
    SELECT * INTO v_customer
    FROM public.customers
    WHERE id = p_customer_id;

    IF v_customer.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT public.tanda1_user_has_role(v_customer.tenant_id, ARRAY['admin', 'operator']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    v_display_name := CASE
        WHEN p_patch ? 'display_name' THEN trim(COALESCE(p_patch->>'display_name', ''))
        ELSE v_customer.display_name
    END;

    IF NOT public.customer_display_name_is_valid(v_display_name) THEN
        RETURN jsonb_build_object('error', 'invalid_display_name');
    END IF;

    v_tax_id := CASE
        WHEN p_patch ? 'tax_id' THEN NULLIF(upper(trim(COALESCE(p_patch->>'tax_id', ''))), '')
        ELSE v_customer.tax_id
    END;

    v_preferred_currency := CASE
        WHEN p_patch ? 'preferred_currency' THEN COALESCE(NULLIF(upper(trim(COALESCE(p_patch->>'preferred_currency', ''))), ''), 'MXN')
        ELSE v_customer.preferred_currency
    END;

    IF v_preferred_currency NOT IN ('MXN', 'USD') THEN
        RETURN jsonb_build_object('error', 'invalid_preferred_currency');
    END IF;

    IF v_tax_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.customers c
        WHERE c.tenant_id = v_customer.tenant_id
          AND c.id <> v_customer.id
          AND lower(btrim(c.tax_id)) = lower(v_tax_id)
    ) THEN
        RETURN jsonb_build_object('error', 'tax_id_exists');
    END IF;

    IF public.customer_normalize_display_name(v_display_name) <> public.customer_normalize_display_name(v_customer.display_name) THEN
        v_probable_duplicates := public.customer_probable_duplicates_json(v_customer.tenant_id, v_display_name, v_customer.id);
        IF NOT v_confirm_duplicate AND jsonb_array_length(v_probable_duplicates) > 0 THEN
            RETURN jsonb_build_object(
                'error', 'probable_duplicate_display_name',
                'probable_duplicates', v_probable_duplicates
            );
        END IF;
    END IF;

    UPDATE public.customers
    SET display_name = v_display_name,
        legal_name = CASE WHEN p_patch ? 'legal_name' THEN NULLIF(trim(COALESCE(p_patch->>'legal_name', '')), '') ELSE legal_name END,
        primary_contact_name = CASE WHEN p_patch ? 'primary_contact_name' THEN NULLIF(trim(COALESCE(p_patch->>'primary_contact_name', '')), '') ELSE primary_contact_name END,
        primary_contact_email = CASE WHEN p_patch ? 'primary_contact_email' THEN NULLIF(trim(COALESCE(p_patch->>'primary_contact_email', '')), '') ELSE primary_contact_email END,
        primary_contact_phone = CASE WHEN p_patch ? 'primary_contact_phone' THEN NULLIF(trim(COALESCE(p_patch->>'primary_contact_phone', '')), '') ELSE primary_contact_phone END,
        tax_id = CASE WHEN p_patch ? 'tax_id' THEN v_tax_id ELSE tax_id END,
        billing_email = CASE WHEN p_patch ? 'billing_email' THEN NULLIF(trim(COALESCE(p_patch->>'billing_email', '')), '') ELSE billing_email END,
        preferred_currency = v_preferred_currency,
        notes = CASE WHEN p_patch ? 'notes' THEN NULLIF(trim(COALESCE(p_patch->>'notes', '')), '') ELSE notes END,
        updated_at = now()
    WHERE id = p_customer_id;

    PERFORM public.rpc_write_audit(
        v_customer.tenant_id,
        'update_customer',
        'customer',
        p_customer_id,
        jsonb_build_object('keys', ARRAY(SELECT jsonb_object_keys(p_patch)))
    );

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'tax_id_exists');
END;
$function$

public.rpc_update_customer_preferred_cur.definition:
CREATE OR REPLACE FUNCTION public.rpc_update_customer_preferred_currency(p_customer_id uuid, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_customer public.customers%rowtype;
    v_currency text := COALESCE(NULLIF(upper(trim(p_currency)), ''), 'MXN');
BEGIN
    SELECT *
    INTO v_customer
    FROM public.customers
    WHERE id = p_customer_id;

    IF v_customer.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT public.tanda2_user_has_role(v_customer.tenant_id, ARRAY['admin', 'finance']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_currency NOT IN ('MXN', 'USD') THEN
        RETURN jsonb_build_object('error', 'invalid_currency');
    END IF;

    UPDATE public.customers
    SET preferred_currency = v_currency,
        updated_at = now()
    WHERE id = p_customer_id;

    PERFORM public.rpc_write_audit(
        v_customer.tenant_id,
        'update_customer_preferred_currency',
        'customer',
        p_customer_id,
        jsonb_build_object('preferred_currency', v_currency)
    );

    RETURN jsonb_build_object('success', true, 'id', p_customer_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_update_driver(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_update_driver(p_driver_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_driver public.drivers%rowtype;
BEGIN
    SELECT *
    INTO v_driver
    FROM public.drivers
    WHERE id = p_driver_id;

    IF v_driver.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
