public.rpc_upsert_billing_document_tax(u.definition:
CREATE OR REPLACE FUNCTION public.rpc_upsert_billing_document_tax(p_document_id uuid, p_tax jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_document public.billing_documents%rowtype;
    v_tax_id uuid := NULLIF(p_tax->>'id', '')::uuid;
    v_line_id uuid := NULLIF(p_tax->>'line_id', '')::uuid;
    v_tax_scope text;
BEGIN
    SELECT *
    INTO v_document
    FROM private.fiscal02_legacy_billing_documents
    WHERE id = p_document_id;

    IF v_document.id IS NULL THEN
        RETURN jsonb_build_object('error', 'document_not_found');
    END IF;

    IF NOT public.billing_user_has_tenant(v_document.tenant_id, ARRAY['admin', 'operator']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_document.status IN ('queued', 'stamped', 'cancelled', 'voided') THEN
        RETURN jsonb_build_object('error', 'document_locked');
    END IF;

    IF v_line_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM public.billing_document_lines l
        WHERE l.id = v_line_id
          AND l.document_id = p_document_id
          AND l.tenant_id = v_document.tenant_id
    ) THEN
        RETURN jsonb_build_object('error', 'line_not_found');
    END IF;

    v_tax_scope := COALESCE(NULLIF(trim(p_tax->>'tax_scope'), ''), CASE WHEN v_line_id IS NULL THEN 'global' ELSE 'line' END);

    IF v_tax_scope = 'line' AND v_line_id IS NULL THEN
        RETURN jsonb_build_object('error', 'line_tax_requires_line_id');
    END IF;

    IF v_tax_scope = 'global' THEN
        v_line_id := NULL;
    END IF;

    IF v_tax_id IS NOT NULL THEN
        UPDATE public.billing_document_taxes
        SET line_id = v_line_id,
            tax_scope = v_tax_scope,
            tax_type = COALESCE(NULLIF(trim(COALESCE(p_tax->>'tax_type', '')), ''), tax_type),
            tax_code = COALESCE(NULLIF(trim(COALESCE(p_tax->>'tax_code', '')), ''), tax_code),
            factor_type = CASE WHEN p_tax ? 'factor_type' THEN NULLIF(trim(COALESCE(p_tax->>'factor_type', '')), '') ELSE factor_type END,
            rate_or_quota = CASE WHEN p_tax ? 'rate_or_quota' THEN NULLIF(p_tax->>'rate_or_quota', '')::numeric ELSE rate_or_quota END,
            base = COALESCE(NULLIF(p_tax->>'base', '')::numeric, base),
            amount = COALESCE(NULLIF(p_tax->>'amount', '')::numeric, amount),
            metadata = CASE WHEN p_tax ? 'metadata' THEN COALESCE(p_tax->'metadata', '{}'::jsonb) ELSE metadata END,
            updated_at = now()
        WHERE id = v_tax_id
          AND document_id = p_document_id
          AND tenant_id = v_document.tenant_id;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('error', 'tax_not_found');
        END IF;
    ELSE
        INSERT INTO public.billing_document_taxes (
            tenant_id,
            document_id,
            line_id,
            tax_scope,
            tax_type,
            tax_code,
            factor_type,
            rate_or_quota,
            base,
            amount,
            metadata
        ) VALUES (
            v_document.tenant_id,
            p_document_id,
            v_line_id,
            v_tax_scope,
            COALESCE(NULLIF(trim(COALESCE(p_tax->>'tax_type', '')), ''), 'traslado'),
            COALESCE(NULLIF(trim(COALESCE(p_tax->>'tax_code', '')), ''), '002'),
            NULLIF(trim(COALESCE(p_tax->>'factor_type', '')), ''),
            NULLIF(p_tax->>'rate_or_quota', '')::numeric,
            COALESCE(NULLIF(p_tax->>'base', '')::numeric, 0),
            COALESCE(NULLIF(p_tax->>'amount', '')::numeric, 0),
            COALESCE(p_tax->'metadata', '{}'::jsonb)
        )
        RETURNING id INTO v_tax_id;
    END IF;

    PERFORM public.billing_recalculate_document_totals(p_document_id);

    RETURN jsonb_build_object(
        'success', true,
        'id', v_tax_id,
        'document', public.billing_fiscal_document_json(p_document_id)
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_upsert_currency_exchange_rate.definition:
CREATE OR REPLACE FUNCTION public.rpc_upsert_currency_exchange_rate(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_base text := COALESCE(NULLIF(upper(trim(p_payload->>'base_currency')), ''), 'USD');
    v_quote text := COALESCE(NULLIF(upper(trim(p_payload->>'quote_currency')), ''), 'MXN');
    v_rate_date date := COALESCE(NULLIF(p_payload->>'rate_date', '')::date, current_date);
    v_source text := COALESCE(NULLIF(trim(p_payload->>'source'), ''), 'manual');
BEGIN
    IF NOT public.tanda2_user_has_role(p_tenant_id, ARRAY['admin', 'finance']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_base NOT IN ('MXN', 'USD') OR v_quote NOT IN ('MXN', 'USD') OR v_base = v_quote THEN
        RETURN jsonb_build_object('error', 'invalid_currency_pair');
    END IF;

    IF COALESCE(NULLIF(p_payload->>'rate', '')::numeric, 0) <= 0 THEN
        RETURN jsonb_build_object('error', 'invalid_exchange_rate');
    END IF;

    INSERT INTO public.currency_exchange_rates (
        tenant_id,
        base_currency,
        quote_currency,
        rate_date,
        rate,
        source,
        notes,
        created_by
    ) VALUES (
        p_tenant_id,
        v_base,
        v_quote,
        v_rate_date,
        (p_payload->>'rate')::numeric,
        v_source,
        NULLIF(trim(COALESCE(p_payload->>'notes', '')), ''),
        auth.uid()
    )
    ON CONFLICT (tenant_id, base_currency, quote_currency, rate_date, source)
    DO UPDATE SET
        rate = EXCLUDED.rate,
        notes = EXCLUDED.notes,
        updated_at = now()
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('success', true, 'id', v_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_validate_billing_document_for.definition:
CREATE OR REPLACE FUNCTION public.rpc_validate_billing_document_for_api(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_document public.billing_documents%rowtype;
    v_blockers jsonb := '[]'::jsonb;
    v_warnings jsonb := '[]'::jsonb;
    v_payload jsonb;
    v_status text;
BEGIN
    SELECT *
    INTO v_document
    FROM private.fiscal02_legacy_billing_documents
    WHERE id = p_document_id;

    IF v_document.id IS NULL THEN
        RETURN jsonb_build_object('error', 'document_not_found');
    END IF;

    IF NOT public.billing_user_has_tenant(v_document.tenant_id, ARRAY['admin', 'operator']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    PERFORM public.billing_recalculate_document_totals(p_document_id);

    SELECT *
    INTO v_document
    FROM private.fiscal02_legacy_billing_documents
    WHERE id = p_document_id;

    IF NOT EXISTS (
        SELECT 1 FROM public.billing_document_parties p
        WHERE p.document_id = p_document_id
          AND p.role = 'issuer'
          AND NULLIF(trim(COALESCE(p.rfc, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.legal_name, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.fiscal_regime_code, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.fiscal_postal_code, '')), '') IS NOT NULL
    ) THEN
        v_blockers := v_blockers || jsonb_build_array('missing_complete_issuer');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.billing_document_parties p
        WHERE p.document_id = p_document_id
          AND p.role = 'receiver'
          AND NULLIF(trim(COALESCE(p.rfc, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.legal_name, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.fiscal_regime_code, '')), '') IS NOT NULL
          AND NULLIF(trim(COALESCE(p.fiscal_postal_code, '')), '') IS NOT NULL
    ) THEN
        v_blockers := v_blockers || jsonb_build_array('missing_complete_receiver');
    END IF;

    IF NULLIF(trim(COALESCE(v_document.currency, '')), '') IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array('missing_currency');
    END IF;

    IF NULLIF(trim(COALESCE(v_document.payment_form_code, '')), '') IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array('missing_payment_form');
    END IF;

    IF NULLIF(trim(COALESCE(v_document.payment_method_code, '')), '') IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array('missing_payment_method');
    END IF;

    IF v_document.document_type IN ('cfdi_ingreso', 'cfdi_egreso')
       AND NULLIF(trim(COALESCE(v_document.cfdi_use_code, '')), '') IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array('missing_cfdi_use');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.billing_document_lines l
        WHERE l.document_id = p_document_id
    ) THEN
        v_blockers := v_blockers || jsonb_build_array('missing_concepts');
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.billing_document_lines l
        WHERE l.document_id = p_document_id
          AND (
              NULLIF(trim(COALESCE(l.description, '')), '') IS NULL
              OR NULLIF(trim(COALESCE(l.product_service_key, '')), '') IS NULL
              OR NULLIF(trim(COALESCE(l.unit_key, '')), '') IS NULL
              OR NULLIF(trim(COALESCE(l.object_tax_code, '')), '') IS NULL
              OR l.quantity <= 0
              OR l.unit_price < 0
          )
    ) THEN
        v_blockers := v_blockers || jsonb_build_array('incomplete_concepts');
    END IF;

    IF v_document.total <= 0 THEN
        v_blockers := v_blockers || jsonb_build_array('total_must_be_greater_than_zero');
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.billing_document_lines l
        WHERE l.document_id = p_document_id
          AND l.object_tax_code = '02'
          AND NOT EXISTS (
              SELECT 1 FROM public.billing_document_taxes t
              WHERE t.line_id = l.id
          )
    ) THEN
        v_warnings := v_warnings || jsonb_build_array('taxable_concepts_without_tax_lines');
    END IF;

    IF v_document.operation_id IS NULL THEN
        v_warnings := v_warnings || jsonb_build_array('document_not_linked_to_operation');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.billing_fiscal_profiles fp
        WHERE fp.tenant_id = v_document.tenant_id
          AND fp.api_enabled = true
    ) THEN
        v_warnings := v_warnings || jsonb_build_array('api_not_enabled_yet');
    END IF;

    v_payload := public.billing_build_api_payload(p_document_id);

    v_status := CASE
        WHEN jsonb_array_length(v_blockers) = 0
             AND v_document.status IN ('draft', 'api_error') THEN 'ready_for_api'
        WHEN jsonb_array_length(v_blockers) > 0
             AND v_document.status = 'ready_for_api' THEN 'draft'
        ELSE v_document.status
    END;

    UPDATE public.billing_documents
    SET validation_blockers = v_blockers,
        validation_warnings = v_warnings,
        api_payload = COALESCE(v_payload, '{}'::jsonb),
        status = v_status,
        updated_at = now()
    WHERE id = p_document_id;

    RETURN jsonb_build_object(
        'success', true,
        'blockers', v_blockers,
        'warnings', v_warnings,
        'status', v_status,
        'document', public.billing_fiscal_document_json(p_document_id)
    );
END;
$function$

public.rpc_void_operation_billing(uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_void_operation_billing(p_operation_id uuid, p_void_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_billing public.operation_billing%rowtype;
    v_reason text := NULLIF(trim(COALESCE(p_void_reason, '')), '');
BEGIN
    SELECT *
    INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_reason IS NULL THEN
        RETURN jsonb_build_object('error', 'missing_void_reason');
    END IF;

    SELECT *
    INTO v_billing
    FROM public.operation_billing
    WHERE operation_id = p_operation_id;

    IF v_billing.id IS NULL THEN
        RETURN jsonb_build_object('error', 'billing_record_missing');
    END IF;

    IF v_billing.status <> 'issued' THEN
        RETURN jsonb_build_object('error', 'invalid_billing_status');
    END IF;

    UPDATE public.operation_billing
    SET status = 'voided',
        voided_at = now(),
        voided_by = auth.uid(),
        void_reason = v_reason,
        updated_at = now()
    WHERE id = v_billing.id;

    PERFORM public.rpc_write_audit(
        v_operation.tenant_id,
        'void_operation_billing',
        'operation_billing',
        v_billing.id,
        jsonb_build_object(
            'operation_id', p_operation_id,
            'void_reason', v_reason
        )
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.tanda4_generated_documents_defaul.definition:
CREATE OR REPLACE FUNCTION public.tanda4_generated_documents_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_prefix text;
    v_count integer;
BEGIN
    IF NEW.template_version_id IS NULL AND NEW.template_id IS NOT NULL THEN
        SELECT active_version_id INTO NEW.template_version_id
        FROM public.document_templates
        WHERE id = NEW.template_id;
    END IF;

    IF NEW.document_number IS NULL OR trim(NEW.document_number) = '' THEN
        v_prefix := public.tanda4_document_prefix(NEW.entity_type);
        SELECT count(*) + 1 INTO v_count
        FROM public.generated_documents
        WHERE tenant_id = NEW.tenant_id
          AND entity_type = NEW.entity_type
          AND date_trunc('month', generated_at) = date_trunc('month', now());
        NEW.document_number := v_prefix || '-' || to_char(now(), 'YYMM') || '-' || lpad(v_count::text, 4, '0');
    END IF;

    IF NEW.status = 'final' AND NEW.finalized_at IS NULL THEN
        NEW.finalized_at := COALESCE(NEW.generated_at, now());
    END IF;

    RETURN NEW;
END;
$function$

public.tanda4_render_document_html(uuid,.definition:
CREATE OR REPLACE FUNCTION public.tanda4_render_document_html(p_version_id uuid, p_data jsonb, p_document_number text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_version public.document_template_versions%rowtype;
    v_settings public.tenant_settings%rowtype;
    v_brand_name text;
    v_primary_color text;
    v_logo_url text;
    v_fields_html text := '';
    v_amounts_html text := '';
    v_notes_html text := '';
    v_payment_html text := '';
    v_signature_html text := '';
    v_sections_html text := '';
    v_source_label text;
    v_layout_key text;
    v_show_amounts boolean;
    v_show_payment boolean;
    v_show_signature boolean;
    v_payment_instructions text;
    v_signature_label text;
    v_order text[];
    v_section text;
BEGIN
    SELECT * INTO v_version
    FROM public.document_template_versions
    WHERE id = p_version_id;

    IF v_version.id IS NULL THEN
        RETURN '<html><body><p>Plantilla no encontrada.</p></body></html>';
    END IF;

    SELECT * INTO v_settings
    FROM public.tenant_settings
    WHERE tenant_id = v_version.tenant_id
    LIMIT 1;

    v_brand_name := COALESCE(NULLIF(v_version.brand_settings->>'brand_name', ''), v_settings.brand_name, 'ROTERO');
    v_primary_color := COALESCE(NULLIF(v_version.brand_settings->>'primary_color', ''), v_settings.primary_color, '#0F2B5B');
    v_logo_url := COALESCE(NULLIF(v_version.brand_settings->>'logo_url', ''), v_settings.logo_url);
    v_source_label := COALESCE(NULLIF(p_data->>'source_label', ''), p_document_number);
    v_layout_key := COALESCE(NULLIF(v_version.layout_key, ''), 'standard');
    v_show_amounts := public.tanda7_bool_setting(v_version.brand_settings, 'show_amounts', true);
    v_show_payment := public.tanda7_bool_setting(v_version.brand_settings, 'show_payment_block', false);
    v_show_signature := public.tanda7_bool_setting(v_version.brand_settings, 'show_signature_block', false);
    v_payment_instructions := NULLIF(v_version.brand_settings->>'payment_instructions', '');
    v_signature_label := COALESCE(NULLIF(v_version.brand_settings->>'signature_label', ''), 'Firma de recibido');
    v_order := public.tanda7_section_order(v_version.brand_settings);

    IF array_length(v_order, 1) IS NULL THEN
        v_order := ARRAY['fields', 'amounts', 'notes', 'payment', 'signature'];
    END IF;

    SELECT COALESCE(string_agg(
        '<tr><th>' || public.tanda4_escape_html(item->>'label') || '</th><td>' || public.tanda4_escape_html(item->>'value') || '</td></tr>',
        ''
    ), '')
    INTO v_fields_html
    FROM jsonb_array_elements(COALESCE(p_data->'fields', '[]'::jsonb)) AS field(item)
    WHERE public.tanda4_field_visible(v_version.visible_fields, item);

    v_fields_html := '<section class="section fields"><h2>Detalle</h2><table class="kv"><tbody>' ||
        CASE WHEN v_fields_html = '' THEN '<tr><td class="empty">Sin campos visibles configurados.</td></tr>' ELSE v_fields_html END ||
        '</tbody></table></section>';

    SELECT COALESCE(string_agg(
        '<div class="amount"><span>' || public.tanda4_escape_html(item->>'label') || '</span><strong>' || public.tanda4_escape_html(item->>'value') || '</strong></div>',
        ''
    ), '')
    INTO v_amounts_html
    FROM jsonb_array_elements(COALESCE(p_data->'amounts', '[]'::jsonb)) AS amount(item);

    v_amounts_html := CASE
        WHEN v_show_amounts THEN '<section class="section amounts"><h2>Importes</h2>' ||
            CASE WHEN v_amounts_html = '' THEN '<p class="empty">Sin importes configurados.</p>' ELSE v_amounts_html END ||
            '</section>'
        ELSE ''
    END;

    v_notes_html := CASE
        WHEN NULLIF(p_data->>'notes', '') IS NULL THEN ''
        ELSE '<section class="section notes"><h2>Notas</h2><p>' || public.tanda4_escape_html(p_data->>'notes') || '</p></section>'
    END;

    v_payment_html := CASE
        WHEN v_show_payment AND v_payment_instructions IS NOT NULL THEN
            '<section class="section payment"><h2>Indicaciones de pago</h2><p>' || public.tanda4_escape_html(v_payment_instructions) || '</p></section>'
        ELSE ''
    END;

    v_signature_html := CASE
        WHEN v_show_signature THEN
            '<section class="section signature"><div class="signature-line"></div><p>' || public.tanda4_escape_html(v_signature_label) || '</p></section>'
        ELSE ''
    END;

    FOREACH v_section IN ARRAY v_order LOOP
        v_sections_html := v_sections_html || CASE v_section
            WHEN 'fields' THEN v_fields_html
            WHEN 'amounts' THEN v_amounts_html
            WHEN 'notes' THEN v_notes_html
            WHEN 'payment' THEN v_payment_html
            WHEN 'signature' THEN v_signature_html
            ELSE ''
        END;
    END LOOP;

    RETURN '<!doctype html><html><head><meta charset="utf-8" />' ||
        '<title>' || public.tanda4_escape_html(COALESCE(NULLIF(v_version.title, ''), p_data->>'title', 'Documento ROTERO')) || '</title>' ||
        '<style>' ||
        ':root{--primary:' || public.tanda4_escape_html(v_primary_color) || ';--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f8fafc;}' ||
        '@page{size:letter;margin:14mm;}' ||
        '*{box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;color:var(--ink);margin:0;background:#fff;font-size:' ||
        CASE WHEN v_layout_key = 'compact' THEN '11px' ELSE '12px' END ||
        ';line-height:1.45;}' ||
        '.page{max-width:820px;margin:0 auto;padding:' || CASE WHEN v_layout_key = 'compact' THEN '20px' ELSE '28px' END || ';}' ||
        '.header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;border-bottom:4px solid var(--primary);padding-bottom:16px;margin-bottom:22px;}' ||
        '.brand{display:flex;align-items:center;gap:12px;min-width:0}.logo{width:56px;height:56px;object-fit:contain;border:1px solid var(--line);border-radius:8px;padding:4px;}.brand-name{font-size:22px;font-weight:800;color:var(--primary);}.muted{color:var(--muted);font-size:11px}.doc-meta{text-align:right;min-width:180px}.doc-number{font-size:18px;font-weight:800}.title{font-size:24px;font-weight:800;margin:0 0 8px;color:var(--ink)}.body-text{white-space:pre-line;margin:0 0 18px;color:#334155}.section{border:1px solid var(--line);border-radius:8px;padding:14px;margin-top:14px;background:#fff}.section h2{margin:0 0 10px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--primary)}.kv{width:100%;border-collapse:collapse}.kv th{width:38%;text-align:left;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.04em;padding:8px;border-bottom:1px solid var(--line)}.kv td{padding:8px;border-bottom:1px solid var(--line);font-weight:600}.amount{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:9px 0}.amount span{color:var(--muted)}.amount strong{font-size:15px}.notes,.payment{background:var(--soft)}.notes p,.payment p{margin:0;white-space:pre-line;color:#334155}.signature{margin-top:34px;text-align:center}.signature-line{height:1px;background:var(--line);width:260px;margin:24px auto 8px}.empty{color:var(--muted);font-style:italic}.footer{margin-top:28px;border-top:1px solid var(--line);padding-top:12px;color:var(--muted);font-size:11px;display:flex;justify-content:space-between;gap:16px}.legal{margin-top:12px;color:#94a3b8;font-size:10px;white-space:pre-line}@media print{body{background:#fff}.page{padding:0;max-width:none}.no-print{display:none!important}}' ||
        '</style></head><body><main class="page">' ||
        '<header class="header"><div class="brand">' ||
        CASE WHEN v_logo_url IS NULL THEN '' ELSE '<img class="logo" src="' || public.tanda4_escape_html(v_logo_url) || '" alt="Logo" />' END ||
        '<div><div class="brand-name">' || public.tanda4_escape_html(v_brand_name) || '</div><div class="muted">' || public.tanda4_escape_html(COALESCE(v_version.footer_text, 'ROTERO ERP')) || '</div></div></div>' ||
        '<div class="doc-meta"><div class="muted">' || public.tanda4_escape_html(public.tanda4_document_type_label(v_version.template_type)) || '</div><div class="doc-number">' || public.tanda4_escape_html(p_document_number) || '</div><div class="muted">' || to_char(now(), 'YYYY-MM-DD HH24:MI') || '</div></div></header>' ||
        '<section><h1 class="title">' || public.tanda4_escape_html(COALESCE(NULLIF(v_version.title, ''), p_data->>'title', public.tanda4_document_type_label(v_version.template_type))) || '</h1>' ||
        '<p class="body-text">' || public.tanda4_escape_html(COALESCE(NULLIF(v_version.body_text, ''), 'Documento generado desde ROTERO ERP.')) || '</p></section>' ||
        v_sections_html ||
        '<footer class="footer"><span>' || public.tanda4_escape_html(v_source_label) || '</span><span>Generado en ROTERO ERP</span></footer>' ||
        CASE WHEN NULLIF(v_version.legal_notes, '') IS NULL THEN '' ELSE '<div class="legal">' || public.tanda4_escape_html(v_version.legal_notes) || '</div>' END ||
        '</main></body></html>';
END;
$function$

public.tanda6_can_mutate_area(uuid, text.definition:
CREATE OR REPLACE FUNCTION public.tanda6_can_mutate_area(p_tenant_id uuid, p_area text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_role text := public.tanda6_user_role(p_tenant_id);
    v_area text := lower(COALESCE(p_area, ''));
BEGIN
    IF v_role IS NULL THEN
        RETURN false;
    END IF;

    IF v_role = 'admin' THEN
        RETURN true;
    END IF;

    IF v_role = 'finance' THEN
        RETURN v_area IN ('finance', 'billing', 'documents', 'payroll', 'provider');
    END IF;

    IF v_role = 'operator' THEN
        RETURN v_area IN ('operations', 'commercial', 'documents');
    END IF;

    RETURN false;
END;
$function$

