public.tracking_expire_tokens().definition:
CREATE OR REPLACE FUNCTION public.tracking_expire_tokens()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_count INTEGER := 0;
    v_rows  INTEGER := 0;
BEGIN
    -- Tokens cuyo TTL pasó + 48h de gracia → hard_expired
    UPDATE tracking_tokens
    SET state = 'hard_expired'
    WHERE state = 'active'
      AND expires_at + INTERVAL '48 hours' < now();
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_count := v_count + v_rows;

    -- Post-entrega: delivered_at + 96h → hard_expired
    UPDATE tracking_tokens
    SET state = 'hard_expired'
    WHERE state = 'active'
      AND delivered_at IS NOT NULL
      AND delivered_at + INTERVAL '96 hours' < now();
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_count := v_count + v_rows;

    RETURN v_count;
END;
$function$

public.tracking_try_append_route_point(u.definition:
CREATE OR REPLACE FUNCTION public.tracking_try_append_route_point(p_tenant_id uuid, p_operation_id uuid, p_token_id uuid, p_lat double precision, p_lng double precision, p_accuracy double precision DEFAULT NULL::double precision, p_source text DEFAULT 'gps'::text, p_recorded_at timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_last_point RECORD;
    v_dist_m double precision;
BEGIN
    IF p_lat IS NULL OR p_lng IS NULL THEN
        RETURN false;
    END IF;

    SELECT lat, lng, recorded_at
    INTO v_last_point
    FROM tracking_route_points
    WHERE operation_id = p_operation_id
    ORDER BY recorded_at DESC
    LIMIT 1;

    IF v_last_point.recorded_at IS NOT NULL
       AND (COALESCE(p_recorded_at, now()) - v_last_point.recorded_at) <= interval '10 seconds' THEN
        RETURN false;
    END IF;

    IF v_last_point.lat IS NOT NULL THEN
        v_dist_m := haversine_m(v_last_point.lat, v_last_point.lng, p_lat, p_lng);
    END IF;

    IF v_last_point.lat IS NOT NULL AND v_dist_m IS NOT NULL AND v_dist_m < 15 THEN
        RETURN false;
    END IF;

    INSERT INTO tracking_route_points (
        tenant_id,
        operation_id,
        token_id,
        recorded_at,
        lat,
        lng,
        accuracy_m,
        source
    ) VALUES (
        p_tenant_id,
        p_operation_id,
        p_token_id,
        COALESCE(p_recorded_at, now()),
        p_lat,
        p_lng,
        p_accuracy,
        COALESCE(p_source, 'gps')
    );

    RETURN true;
END;
$function$

public.rpc_add_deal_activity(uuid, jsonb.definition:
CREATE OR REPLACE FUNCTION public.rpc_add_deal_activity(p_deal_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    cur_tenant_id uuid;
    new_id uuid;
BEGIN
    SELECT tenant_id INTO cur_tenant_id FROM crm_deals WHERE id = p_deal_id;
    IF cur_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = cur_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    INSERT INTO crm_deal_activity (
        tenant_id,
        deal_id,
        type,
        body,
        created_by
    ) VALUES (
        cur_tenant_id,
        p_deal_id,
        p_payload->>'type',
        p_payload->>'body',
        auth.uid()
    ) RETURNING id INTO new_id;
    
    -- touch the deal
    UPDATE crm_deals SET last_touch_at = now(), updated_at = now() WHERE id = p_deal_id;

    RETURN jsonb_build_object('success', true, 'id', new_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_add_deal_note(uuid, text).definition:
CREATE OR REPLACE FUNCTION public.rpc_add_deal_note(p_deal_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
      DECLARE v_tenant uuid;v_id uuid;
      BEGIN
        SELECT tenant_id INTO v_tenant FROM public.crm_deals WHERE id=p_deal_id;
        IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','not_found'); END IF;
        IF NOT public.tanda1_user_has_role(v_tenant,ARRAY['admin','operator']) THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
        IF NULLIF(btrim(p_note),'') IS NULL THEN RETURN jsonb_build_object('error','invalid_payload'); END IF;
        INSERT INTO public.crm_deal_notes(tenant_id,deal_id,author_user_id,note) VALUES(v_tenant,p_deal_id,auth.uid(),p_note) RETURNING id INTO v_id;
        INSERT INTO public.audit_log(tenant_id,actor_user_id,action,entity_type,entity_id,metadata)
        VALUES(v_tenant,auth.uid(),'note_added','deal',p_deal_id,jsonb_build_object('note_preview',left(p_note,50)));
        RETURN jsonb_build_object('id',v_id);
      END $function$

public.rpc_create_cfdi(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_create_cfdi(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    new_id uuid;
    v_uuid text;
    v_status text;
    v_total numeric;
    v_subtotal numeric;
    v_currency text;
    v_exchange_rate numeric;
    v_exchange_rate_date date;
BEGIN
    IF NOT public.tanda2_user_has_role(p_tenant_id, ARRAY['admin', 'finance']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    v_uuid := p_payload->>'uuid';
    v_status := COALESCE(NULLIF(p_payload->>'status', ''), 'timbrado');
    v_total := COALESCE(NULLIF(p_payload->>'total', '')::numeric, 0);
    v_subtotal := NULLIF(p_payload->>'subtotal', '')::numeric;
    v_currency := COALESCE(NULLIF(upper(trim(p_payload->>'currency')), ''), 'MXN');
    v_exchange_rate := NULLIF(p_payload->>'exchange_rate', '')::numeric;
    v_exchange_rate_date := NULLIF(p_payload->>'exchange_rate_date', '')::date;

    IF v_status != 'draft' AND (v_uuid IS NULL OR trim(v_uuid) = '') THEN
        v_uuid := 'manual-' || gen_random_uuid()::text;
    END IF;

    IF v_status != 'draft' AND v_total <= 0 THEN
        RETURN jsonb_build_object('error', 'total_must_be_positive');
    END IF;

    IF v_currency = 'MXN' THEN
        v_exchange_rate := 1;
        v_exchange_rate_date := COALESCE(v_exchange_rate_date, COALESCE(NULLIF(p_payload->>'issued_at', '')::timestamptz::date, current_date));
    ELSIF v_status <> 'draft' AND (v_exchange_rate IS NULL OR v_exchange_rate <= 0 OR v_exchange_rate_date IS NULL) THEN
        RETURN jsonb_build_object('error', 'exchange_rate_required_for_usd');
    END IF;

    INSERT INTO public.billing_cfdis (
        tenant_id,
        uuid,
        serie,
        folio,
        rfc_emisor,
        rfc_receptor,
        receptor_name,
        subtotal,
        total,
        currency,
        status,
        has_carta_porte,
        has_complemento_pago,
        issued_at,
        pac_provider,
        notes,
        exchange_rate,
        exchange_rate_date,
        subtotal_mxn,
        iva_mxn,
        total_mxn
    ) VALUES (
        p_tenant_id,
        COALESCE(NULLIF(v_uuid, ''), 'draft-' || gen_random_uuid()::text),
        p_payload->>'serie',
        p_payload->>'folio',
        p_payload->>'rfc_emisor',
        p_payload->>'rfc_receptor',
        p_payload->>'receptor_name',
        v_subtotal,
        v_total,
        v_currency,
        v_status,
        COALESCE((p_payload->>'has_carta_porte')::boolean, false),
        COALESCE((p_payload->>'has_complemento_pago')::boolean, false),
        COALESCE(NULLIF(p_payload->>'issued_at', '')::timestamptz, now()),
        p_payload->>'pac_provider',
        p_payload->>'notes',
        v_exchange_rate,
        v_exchange_rate_date,
        public.tanda2_amount_mxn(COALESCE(v_subtotal, round(v_total / 1.16, 2)), v_currency, v_exchange_rate),
        public.tanda2_amount_mxn(GREATEST(v_total - COALESCE(v_subtotal, round(v_total / 1.16, 2)), 0), v_currency, v_exchange_rate),
        public.tanda2_amount_mxn(v_total, v_currency, v_exchange_rate)
    ) RETURNING id INTO new_id;

    RETURN jsonb_build_object('success', true, 'id', new_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_create_deal(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_create_deal(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new_id uuid;
    v_quote_reference text;
    v_quote_payload jsonb := COALESCE(p_payload->'quote_payload', '{}'::jsonb);
    v_customer_id uuid := NULLIF(p_payload->>'customer_id', '')::uuid;
    v_customer public.customers%rowtype;
    v_company text := NULLIF(trim(COALESCE(p_payload->>'company', '')), '');
    v_contact_name text := NULLIF(trim(COALESCE(p_payload->>'contact_name', '')), '');
    v_contact_email text := NULLIF(trim(COALESCE(p_payload->>'contact_email', '')), '');
    v_contact_phone text := NULLIF(trim(COALESCE(p_payload->>'contact_phone', '')), '');
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = p_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF NULLIF(trim(COALESCE(p_payload->>'title', '')), '') IS NULL THEN
        RETURN jsonb_build_object('error', 'title_is_required');
    END IF;

    IF NOT public.crm_quote_payload_has_only_allowed_keys(v_quote_payload) THEN
        RETURN jsonb_build_object('error', 'invalid_quote_payload_keys');
    END IF;

    IF v_customer_id IS NOT NULL THEN
        SELECT *
        INTO v_customer
        FROM public.customers
        WHERE id = v_customer_id
          AND tenant_id = p_tenant_id;

        IF v_customer.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_customer');
        END IF;

        IF v_customer.is_active = false THEN
            RETURN jsonb_build_object('error', 'customer_inactive');
        END IF;

        v_company := COALESCE(v_company, v_customer.display_name);
        v_contact_name := COALESCE(v_contact_name, v_customer.primary_contact_name);
        v_contact_email := COALESCE(v_contact_email, v_customer.primary_contact_email);
        v_contact_phone := COALESCE(v_contact_phone, v_customer.primary_contact_phone);
    END IF;

    v_quote_reference := COALESCE(
        NULLIF(trim(COALESCE(p_payload->>'quote_reference', '')), ''),
        public.crm_generate_quote_reference(p_tenant_id)
    );

    INSERT INTO public.crm_deals (
        tenant_id,
        customer_id,
        title,
        company,
        contact_name,
        contact_email,
        contact_phone,
        value,
        currency,
        stage,
        priority,
        notes,
        owner_user_id,
        last_touch_at,
        quote_status,
        quote_reference,
        quote_payload
    ) VALUES (
        p_tenant_id,
        v_customer_id,
        trim(p_payload->>'title'),
        v_company,
        v_contact_name,
        v_contact_email,
        v_contact_phone,
        NULLIF(p_payload->>'value', '')::numeric,
        COALESCE(NULLIF(trim(COALESCE(p_payload->>'currency', '')), ''), 'MXN'),
        COALESCE(NULLIF(trim(COALESCE(p_payload->>'stage', '')), ''), 'qualified'),
        COALESCE(NULLIF(trim(COALESCE(p_payload->>'priority', '')), ''), 'medium'),
        NULLIF(trim(COALESCE(p_payload->>'notes', '')), ''),
        NULLIF(p_payload->>'owner_user_id', '')::uuid,
        now(),
        COALESCE(NULLIF(trim(COALESCE(p_payload->>'quote_status', '')), ''), 'draft'),
        v_quote_reference,
        v_quote_payload
    )
    RETURNING id INTO v_new_id;

    PERFORM public.rpc_write_audit(
        p_tenant_id,
        'create_quote',
        'deal',
        v_new_id,
        jsonb_build_object('quote_reference', v_quote_reference, 'customer_id', v_customer_id)
    );

    RETURN jsonb_build_object('success', true, 'id', v_new_id, 'quote_reference', v_quote_reference);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'quote_reference_exists');
WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_create_operation(uuid, text,.definition:
CREATE OR REPLACE FUNCTION public.rpc_create_operation(p_tenant_id uuid, p_reference_code text, p_route_summary text DEFAULT NULL::text, p_client_display_name text DEFAULT NULL::text, p_destination_city text DEFAULT NULL::text, p_eta_display text DEFAULT NULL::text, p_status text DEFAULT 'planned'::text, p_origin_place jsonb DEFAULT NULL::jsonb, p_destination_place jsonb DEFAULT NULL::jsonb, p_eta timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    new_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = p_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;
    
    INSERT INTO operations (
        tenant_id, reference_code, route_summary, client_display_name, 
        destination_city, eta_display, status, origin_place, destination_place, eta
    )
    VALUES (
        p_tenant_id, p_reference_code, p_route_summary, p_client_display_name,
        p_destination_city, p_eta_display, p_status, p_origin_place, p_destination_place, p_eta
    )
    RETURNING id INTO new_id;
    
    RETURN jsonb_build_object('success', true, 'id', new_id);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'reference_exists');
WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_deactivate_member(uuid, uuid).definition:
CREATE OR REPLACE FUNCTION public.rpc_deactivate_member(p_tenant_id uuid, p_member_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- Only Admins can deactivate
    IF NOT EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = auth.uid() AND m.tenant_id = p_tenant_id AND m.role = 'admin') THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    -- MVP: Hard delete membership to revoke access (or soft delete if we add disabled_at later)
    DELETE FROM memberships WHERE tenant_id = p_tenant_id AND user_id = p_member_user_id;
    
    PERFORM rpc_write_audit(p_tenant_id, 'deactivate_member', 'membership', p_member_user_id, 'null'::jsonb);
    
    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_post_driver_event(text, text,.definition:
CREATE OR REPLACE FUNCTION public.rpc_post_driver_event(p_token text, p_action text, p_source text DEFAULT 'gps'::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_accuracy numeric DEFAULT NULL::numeric, p_municipality text DEFAULT NULL::text, p_state_name text DEFAULT NULL::text, p_country_code character DEFAULT 'MX'::bpchar, p_incident_type text DEFAULT NULL::text, p_incident_note text DEFAULT NULL::text, p_client_timestamp timestamp with time zone DEFAULT now(), p_offline_queued boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
    v_token RECORD;
    v_event_id uuid;
    v_operation_id uuid;
    v_new_status text;
    v_valid_actions text[] := ARRAY['departure','in_transit','arrival','delivered','incident','location_reset'];
    v_suspicious boolean := false;
    v_gps_recorded boolean := false;
    v_client_timestamp timestamptz := COALESCE(p_client_timestamp, now());
    v_last_municipality text;
    v_has_departure boolean := false;
    v_has_arrival boolean := false;
    v_has_delivered boolean := false;
    v_has_duplicate boolean := false;
    v_in_transit_count integer := 0;
BEGIN
    IF p_action IS NULL OR NOT (p_action = ANY(v_valid_actions)) THEN
        RETURN jsonb_build_object('http', 400, 'accepted', false, 'reason', 'invalid_action');
    END IF;

    SELECT * INTO v_token
    FROM tracking_validate_token(p_token, 'driver:write');

    IF v_token IS NULL OR v_token.token_id IS NULL THEN
        RETURN jsonb_build_object('http', 404, 'accepted', false, 'reason', 'not_found');
    END IF;

    IF v_token.token_state = 'revoked' THEN
        RETURN jsonb_build_object('http', 403, 'accepted', false, 'reason', 'revoked');
    END IF;

    IF v_token.token_state IN ('hard_expired', 'soft_expired', 'rotated') OR v_token.expires_at < now() THEN
        RETURN jsonb_build_object('http', 403, 'accepted', false, 'reason', 'expired');
    END IF;

    v_operation_id := v_token.operation_id;

    IF p_accuracy IS NOT NULL AND p_accuracy > 5000 THEN
        v_suspicious := true;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM tracking_events
        WHERE token_id = v_token.token_id
          AND event_type = p_action
          AND abs(extract(epoch FROM (client_timestamp - v_client_timestamp))) <= 5
    ) INTO v_has_duplicate;

    IF v_has_duplicate THEN
        UPDATE tracking_tokens
        SET last_used_at = now()
        WHERE id = v_token.token_id;

        RETURN jsonb_build_object(
            'http', 200,
            'accepted', false,
            'reason', 'duplicate',
            'gpsRecorded', false
        );
    END IF;

    SELECT
        EXISTS (
            SELECT 1
            FROM tracking_events
            WHERE operation_id = v_operation_id
              AND event_type = 'departure'
        ),
        EXISTS (
            SELECT 1
            FROM tracking_events
            WHERE operation_id = v_operation_id
              AND event_type = 'arrival'
        ),
        EXISTS (
            SELECT 1
            FROM tracking_events
            WHERE operation_id = v_operation_id
              AND event_type = 'delivered'
        ),
        COALESCE((
            SELECT count(*)
            FROM tracking_events
            WHERE operation_id = v_operation_id
              AND event_type = 'in_transit'
        ), 0)
    INTO
        v_has_departure,
        v_has_arrival,
        v_has_delivered,
        v_in_transit_count;

    IF p_action = 'departure' AND v_has_departure THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'action_already_done');
    END IF;

    IF p_action = 'in_transit' AND NOT v_has_departure THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'departure_required_first');
    END IF;

    IF p_action = 'in_transit' AND v_has_arrival THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'arrival_already_done');
    END IF;

    IF p_action = 'in_transit' AND v_has_delivered THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'delivered_already_done');
    END IF;

    IF p_action = 'in_transit' AND v_in_transit_count >= 15 THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'max_in_transit_reached');
    END IF;

    IF p_action = 'arrival' AND NOT v_has_departure THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'departure_required_first');
    END IF;

    IF p_action = 'arrival' AND v_has_arrival THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'action_already_done');
    END IF;

    IF p_action = 'arrival' AND v_has_delivered THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'delivered_already_done');
    END IF;

    IF p_action = 'delivered' AND v_has_delivered THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'action_already_done');
    END IF;

    IF p_action = 'delivered' AND NOT v_has_arrival THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'arrival_required_first');
    END IF;

    IF p_action = 'location_reset' AND v_has_delivered THEN
        RETURN jsonb_build_object('http', 422, 'accepted', false, 'reason', 'delivered_already_done');
    END IF;

    IF p_action = 'in_transit' AND NULLIF(trim(COALESCE(p_municipality, '')), '') IS NOT NULL THEN
        SELECT e.municipality
        INTO v_last_municipality
        FROM tracking_events e
        WHERE e.operation_id = v_operation_id
          AND e.event_type NOT IN ('incident', 'location_reset')
          AND e.municipality IS NOT NULL
        ORDER BY e.server_timestamp DESC
        LIMIT 1;

        IF v_last_municipality IS NOT NULL
           AND lower(trim(v_last_municipality)) = lower(trim(p_municipality)) THEN
            IF p_source = 'gps' AND p_lat IS NOT NULL AND p_lng IS NOT NULL AND NOT v_suspicious THEN
                v_gps_recorded := tracking_try_append_route_point(
                    v_token.tenant_id,
                    v_operation_id,
                    v_token.token_id,
                    p_lat::double precision,
                    p_lng::double precision,
                    p_accuracy::double precision,
                    COALESCE(p_source, 'gps'),
                    v_client_timestamp
                );
            END IF;

            UPDATE tracking_tokens
            SET last_used_at = now()
            WHERE id = v_token.token_id;

            RETURN jsonb_build_object(
                'http', 422,
                'accepted', false,
                'reason', 'same_municipality',
                'gpsRecorded', v_gps_recorded
            );
        END IF;
    END IF;

    IF p_action = 'in_transit' AND EXISTS (
        SELECT 1
        FROM tracking_events
        WHERE operation_id = v_operation_id
          AND event_type = 'in_transit'
          AND server_timestamp > now() - interval '30 minutes'
    ) THEN
        IF p_source = 'gps' AND p_lat IS NOT NULL AND p_lng IS NOT NULL AND NOT v_suspicious THEN
            v_gps_recorded := tracking_try_append_route_point(
                v_token.tenant_id,
                v_operation_id,
                v_token.token_id,
                p_lat::double precision,
                p_lng::double precision,
                p_accuracy::double precision,
                COALESCE(p_source, 'gps'),
                v_client_timestamp
            );
        END IF;

        UPDATE tracking_tokens
        SET last_used_at = now()
        WHERE id = v_token.token_id;

        RETURN jsonb_build_object(
            'http', 200,
            'accepted', false,
            'reason', 'cooldown',
            'gpsRecorded', v_gps_recorded
        );
    END IF;

    IF p_action = 'incident' AND EXISTS (
        SELECT 1
        FROM tracking_events
        WHERE operation_id = v_operation_id
          AND event_type = 'incident'
          AND server_timestamp > now() - interval '10 minutes'
    ) THEN
        IF p_source = 'gps' AND p_lat IS NOT NULL AND p_lng IS NOT NULL AND NOT v_suspicious THEN
            v_gps_recorded := tracking_try_append_route_point(
                v_token.tenant_id,
                v_operation_id,
                v_token.token_id,
                p_lat::double precision,
                p_lng::double precision,
                p_accuracy::double precision,
                COALESCE(p_source, 'gps'),
                v_client_timestamp
            );
        END IF;

        UPDATE tracking_tokens
        SET last_used_at = now()
        WHERE id = v_token.token_id;

        RETURN jsonb_build_object(
            'http', 200,
            'accepted', false,
            'reason', 'cooldown',
            'gpsRecorded', v_gps_recorded
        );
    END IF;

    INSERT INTO tracking_events (
        token_id,
        tenant_id,
        operation_id,
        event_type,
        source,
        client_timestamp,
        server_timestamp,
        lat,
        lng,
        accuracy_m,
        municipality,
        state_name,
        country_code,
        incident_type,
        incident_note,
        is_suspicious,
        offline_queued
    ) VALUES (
        v_token.token_id,
        v_token.tenant_id,
        v_operation_id,
        p_action,
        COALESCE(p_source, 'gps'),
        v_client_timestamp,
        now(),
        p_lat,
        p_lng,
        p_accuracy,
        p_municipality,
        p_state_name,
        p_country_code,
        p_incident_type,
        p_incident_note,
        v_suspicious,
        COALESCE(p_offline_queued, false)
    )
    RETURNING id INTO v_event_id;

    IF p_action <> 'location_reset'
       AND p_source = 'gps'
       AND p_lat IS NOT NULL
       AND p_lng IS NOT NULL
       AND NOT v_suspicious THEN
        v_gps_recorded := tracking_try_append_route_point(
            v_token.tenant_id,
            v_operation_id,
            v_token.token_id,
            p_lat::double precision,
            p_lng::double precision,
            p_accuracy::double precision,
            COALESCE(p_source, 'gps'),
            v_client_timestamp
        );
    END IF;

    v_new_status := CASE p_action
        WHEN 'departure' THEN 'in_transit'
        WHEN 'in_transit' THEN 'in_transit'
        WHEN 'arrival' THEN 'at_destination'
        WHEN 'delivered' THEN 'delivered'
        ELSE NULL
    END;

    IF v_new_status IS NOT NULL THEN
        UPDATE operations
        SET status = v_new_status
        WHERE id = v_operation_id
          AND CASE status
            WHEN 'planned' THEN true
            WHEN 'assigned' THEN true
            WHEN 'in_transit' THEN v_new_status IN ('at_destination', 'delivered')
            WHEN 'at_destination' THEN v_new_status = 'delivered'
            ELSE false
          END;
    END IF;

    UPDATE tracking_tokens
    SET
        last_used_at = now(),
        event_count = event_count + 1,
        delivered_at = CASE
            WHEN p_action = 'delivered' THEN COALESCE(delivered_at, now())
            ELSE delivered_at
        END
    WHERE id = v_token.token_id;

    IF p_action = 'delivered' THEN
        UPDATE tracking_tokens
        SET delivered_at = COALESCE(delivered_at, now())
        WHERE operation_id = v_operation_id
          AND scope IN ('public:read', 'driver:write')
          AND state IN ('active', 'soft_expired');
    END IF;

    RETURN jsonb_build_object(
        'http', 200,
        'accepted', true,
        'eventId', v_event_id,
        'gpsRecorded', v_gps_recorded
    );
END;
$function$

public.rpc_reports_financial_summary(uui.definition:
CREATE OR REPLACE FUNCTION public.rpc_reports_financial_summary(p_tenant_id uuid, p_period text DEFAULT 'monthly'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_total_revenue_ytd numeric;
    v_total_expenses_ytd numeric;
    v_net_position numeric;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = auth.uid() AND m.tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    -- For MVP: Assuming YTD logic is simplistic sum over all time if missing year boundaries, or just basic sums
    SELECT COALESCE(SUM(amount), 0) INTO v_total_revenue_ytd FROM private.fiscal02_legacy_finance_invoices WHERE tenant_id = p_tenant_id AND direction = 'ar' AND status IN ('paid', 'open');
    SELECT COALESCE(SUM(amount), 0) INTO v_total_expenses_ytd FROM private.fiscal02_legacy_finance_invoices WHERE tenant_id = p_tenant_id AND direction = 'ap' AND status IN ('paid', 'open');
    v_net_position := v_total_revenue_ytd - v_total_expenses_ytd;

    RETURN jsonb_build_object(
        'revenue_by_month', jsonb_build_array(v_total_revenue_ytd*0.1, v_total_revenue_ytd*0.2, v_total_revenue_ytd*0.15, v_total_revenue_ytd*0.25, v_total_revenue_ytd*0.1, v_total_revenue_ytd*0.2),
        'ar_open_by_month', jsonb_build_array(10, 15, 20, 10, 5, 25),
        'ap_open_by_month', jsonb_build_array(5, 10, 5, 20, 15, 10),
        'cashflow_by_month', jsonb_build_array(100, 200, 150, 300, 250, 400),
        'total_revenue_ytd', v_total_revenue_ytd,
        'total_expenses_ytd', v_total_expenses_ytd,
        'net_position', v_net_position
    );
END;
$function$

public.rpc_toggle_deal_checklist_item(uu.definition:
CREATE OR REPLACE FUNCTION public.rpc_toggle_deal_checklist_item(p_item_id uuid, p_is_done boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
      DECLARE v_tenant uuid;v_deal uuid;
      BEGIN
        SELECT tenant_id,deal_id INTO v_tenant,v_deal FROM public.crm_deal_checklist_items WHERE id=p_item_id;
        IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','not_found'); END IF;
        IF NOT public.tanda1_user_has_role(v_tenant,ARRAY['admin','operator']) THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
        UPDATE public.crm_deal_checklist_items SET is_done=p_is_done,updated_at=now() WHERE id=p_item_id;
        INSERT INTO public.audit_log(tenant_id,actor_user_id,action,entity_type,entity_id,metadata)
        VALUES(v_tenant,auth.uid(),'checklist_updated','deal',v_deal,jsonb_build_object('item_id',p_item_id,'is_done',p_is_done));
        RETURN jsonb_build_object('success',true);
      END $function$

public.rpc_update_cfdi(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_update_cfdi(p_cfdi_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    cur_tenant_id uuid;
    cur_status text;
    new_status text;
BEGIN
    SELECT tenant_id, status INTO cur_tenant_id, cur_status
    FROM private.fiscal02_readable_cfdis
    WHERE id = p_cfdi_id;

    IF cur_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT public.tanda1_user_has_role(cur_tenant_id, ARRAY['admin', 'finance']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_patch ? 'status' THEN
        new_status := p_patch->>'status';
        IF cur_status = 'cancelado' AND new_status = 'timbrado' THEN
            RETURN jsonb_build_object('error', 'cannot_uncancel_cfdi');
        END IF;

        UPDATE public.billing_cfdis
        SET status = new_status,
            cancelled_at = CASE WHEN new_status = 'cancelado' THEN COALESCE(NULLIF(p_patch->>'cancelled_at', '')::timestamptz, now()) ELSE cancelled_at END,
            updated_at = now()
        WHERE id = p_cfdi_id;
    END IF;

    IF p_patch ? 'notes' THEN
        UPDATE public.billing_cfdis SET notes = p_patch->>'notes', updated_at = now() WHERE id = p_cfdi_id;
    END IF;

    IF p_patch ? 'has_carta_porte' THEN
        UPDATE public.billing_cfdis SET has_carta_porte = (p_patch->>'has_carta_porte')::boolean, updated_at = now() WHERE id = p_cfdi_id;
    END IF;

    IF p_patch ? 'has_complemento_pago' THEN
        UPDATE public.billing_cfdis SET has_complemento_pago = (p_patch->>'has_complemento_pago')::boolean, updated_at = now() WHERE id = p_cfdi_id;
    END IF;

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_update_deal(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_update_deal(p_deal_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_deal public.crm_deals%rowtype;
    v_quote_payload jsonb;
    v_should_reopen boolean := false;
    v_new_customer_id uuid;
    v_customer public.customers%rowtype;
    v_customer_changed boolean := false;
    v_company text;
    v_contact_name text;
    v_contact_email text;
    v_contact_phone text;
BEGIN
    SELECT *
    INTO v_deal
    FROM public.crm_deals
    WHERE id = p_deal_id;

    IF v_deal.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_deal.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_deal.quote_status = 'converted' THEN
        RETURN jsonb_build_object('error', 'quote_already_converted');
    END IF;

    IF p_patch ? 'quote_payload' THEN
        v_quote_payload := COALESCE(p_patch->'quote_payload', '{}'::jsonb);
        IF NOT public.crm_quote_payload_has_only_allowed_keys(v_quote_payload) THEN
            RETURN jsonb_build_object('error', 'invalid_quote_payload_keys');
        END IF;
    ELSE
        v_quote_payload := v_deal.quote_payload;
    END IF;

    v_new_customer_id := CASE
        WHEN p_patch ? 'customer_id' THEN NULLIF(p_patch->>'customer_id', '')::uuid
        ELSE v_deal.customer_id
    END;
    v_customer_changed := v_new_customer_id IS DISTINCT FROM v_deal.customer_id;

    IF v_new_customer_id IS NOT NULL THEN
        SELECT *
        INTO v_customer
        FROM public.customers
        WHERE id = v_new_customer_id
          AND tenant_id = v_deal.tenant_id;

        IF v_customer.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_customer');
        END IF;

        IF v_customer_changed AND v_customer.is_active = false THEN
            RETURN jsonb_build_object('error', 'customer_inactive');
        END IF;
    END IF;

    v_should_reopen := v_deal.quote_status = 'approved' AND (
        p_patch ? 'title'
        OR p_patch ? 'company'
        OR p_patch ? 'value'
        OR p_patch ? 'currency'
        OR p_patch ? 'quote_payload'
        OR p_patch ? 'customer_id'
    );

    IF v_customer_changed AND v_new_customer_id IS NOT NULL THEN
        v_company := v_customer.display_name;
        v_contact_name := v_customer.primary_contact_name;
        v_contact_email := v_customer.primary_contact_email;
        v_contact_phone := v_customer.primary_contact_phone;
    ELSE
        v_company := CASE WHEN p_patch ? 'company' THEN NULLIF(trim(COALESCE(p_patch->>'company', '')), '') ELSE v_deal.company END;
        v_contact_name := CASE WHEN p_patch ? 'contact_name' THEN NULLIF(trim(COALESCE(p_patch->>'contact_name', '')), '') ELSE v_deal.contact_name END;
        v_contact_email := CASE WHEN p_patch ? 'contact_email' THEN NULLIF(trim(COALESCE(p_patch->>'contact_email', '')), '') ELSE v_deal.contact_email END;
        v_contact_phone := CASE WHEN p_patch ? 'contact_phone' THEN NULLIF(trim(COALESCE(p_patch->>'contact_phone', '')), '') ELSE v_deal.contact_phone END;
    END IF;

    UPDATE public.crm_deals
    SET customer_id = v_new_customer_id,
        title = COALESCE(NULLIF(trim(COALESCE(p_patch->>'title', '')), ''), title),
        company = v_company,
        contact_name = v_contact_name,
        contact_email = v_contact_email,
        contact_phone = v_contact_phone,
        value = CASE WHEN p_patch ? 'value' THEN NULLIF(p_patch->>'value', '')::numeric ELSE value END,
        currency = COALESCE(NULLIF(trim(COALESCE(p_patch->>'currency', '')), ''), currency),
        priority = COALESCE(NULLIF(trim(COALESCE(p_patch->>'priority', '')), ''), priority),
        notes = CASE WHEN p_patch ? 'notes' THEN NULLIF(trim(COALESCE(p_patch->>'notes', '')), '') ELSE notes END,
        owner_user_id = CASE WHEN p_patch ? 'owner_user_id' THEN NULLIF(p_patch->>'owner_user_id', '')::uuid ELSE owner_user_id END,
        quote_reference = CASE
            WHEN p_patch ? 'quote_reference' THEN COALESCE(NULLIF(trim(COALESCE(p_patch->>'quote_reference', '')), ''), public.crm_generate_quote_reference(v_deal.tenant_id))
            ELSE quote_reference
        END,
        quote_payload = CASE WHEN p_patch ? 'quote_payload' THEN v_quote_payload ELSE quote_payload END,
        quote_status = CASE WHEN v_should_reopen THEN 'in_review' ELSE quote_status END,
        approved_at = CASE WHEN v_should_reopen THEN NULL ELSE approved_at END,
        approved_by = CASE WHEN v_should_reopen THEN NULL ELSE approved_by END,
        approval_note = CASE WHEN v_should_reopen THEN NULL ELSE approval_note END,
        updated_at = now(),
        last_touch_at = now()
    WHERE id = p_deal_id;

    PERFORM public.rpc_write_audit(
        v_deal.tenant_id,
        CASE WHEN v_should_reopen THEN 'update_quote_reopen_review' ELSE 'update_quote' END,
        'deal',
        p_deal_id,
        jsonb_build_object('keys', ARRAY(SELECT jsonb_object_keys(p_patch)), 'customer_id', v_new_customer_id)
    );

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'quote_reference_exists');
WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_update_inventory_lot(uuid, js.definition:
CREATE OR REPLACE FUNCTION public.rpc_update_inventory_lot(p_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    lot_tenant_id uuid;
BEGIN
    SELECT tenant_id INTO lot_tenant_id FROM inventory_lots WHERE id = p_id;
    IF lot_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = lot_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    -----------------------------------
    -- Validate patch keys explicitly.
    -- Allowed: qty_reserved, status, warehouse, description
    -----------------------------------
    IF p_patch ? 'qty_reserved' THEN
        UPDATE inventory_lots SET qty_reserved = (p_patch->>'qty_reserved')::numeric WHERE id = p_id;
    END IF;

    IF p_patch ? 'status' THEN
        UPDATE inventory_lots SET status = p_patch->>'status' WHERE id = p_id;
    END IF;

    IF p_patch ? 'warehouse' THEN
        UPDATE inventory_lots SET warehouse = p_patch->>'warehouse' WHERE id = p_id;
    END IF;

    IF p_patch ? 'description' THEN
        UPDATE inventory_lots SET description = p_patch->>'description' WHERE id = p_id;
    END IF;

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_update_member_role(uuid, uuid.definition:
CREATE OR REPLACE FUNCTION public.rpc_update_member_role(p_tenant_id uuid, p_member_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.tanda1_user_has_role(p_tenant_id, ARRAY['admin']) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_new_role NOT IN ('admin', 'operator', 'finance', 'viewer') THEN
        RETURN jsonb_build_object('error', 'invalid_role');
    END IF;

    UPDATE public.memberships
    SET role = p_new_role
    WHERE tenant_id = p_tenant_id
      AND user_id = p_member_user_id;

    PERFORM public.rpc_write_audit(p_tenant_id, 'update_role', 'membership', p_member_user_id, jsonb_build_object('new_role', p_new_role));

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_update_operation_details(uuid.definition:
CREATE OR REPLACE FUNCTION public.rpc_update_operation_details(p_operation_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_operation public.operations%rowtype;
    v_locked_fields text[] := ARRAY[
        'client_display_name',
        'customer_id',
        'operation_scope',
        'execution_type',
        'service_type',
        'origin_place',
        'destination_place',
        'destination_city',
        'operational_window_start',
        'operational_window_end',
        'cargo_summary',
        'route_summary'
    ];
    v_field text;
    v_new_customer_id uuid;
    v_customer public.customers%rowtype;
    v_scope text;
    v_execution_type text;
BEGIN
    SELECT * INTO v_operation
    FROM public.operations
    WHERE id = p_operation_id;

    IF v_operation.id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = v_operation.tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF v_operation.status IN ('in_transit', 'delivered', 'cancelled', 'closed') THEN
        FOREACH v_field IN ARRAY v_locked_fields LOOP
            IF p_patch ? v_field THEN
                RETURN jsonb_build_object('error', 'field_locked_in_execution', 'field', v_field);
            END IF;
        END LOOP;
    END IF;

    v_scope := CASE
        WHEN p_patch ? 'operation_scope' THEN COALESCE(NULLIF(trim(p_patch->>'operation_scope'), ''), v_operation.operation_scope)
        ELSE v_operation.operation_scope
    END;

    IF v_scope NOT IN ('national', 'international') THEN
        RETURN jsonb_build_object('error', 'invalid_operation_scope');
    END IF;

    v_execution_type := CASE
        WHEN p_patch ? 'execution_type' THEN COALESCE(NULLIF(trim(p_patch->>'execution_type'), ''), v_operation.execution_type)
        ELSE v_operation.execution_type
    END;

    IF v_execution_type NOT IN ('third_party', 'own_fleet') THEN
        RETURN jsonb_build_object('error', 'invalid_execution_type');
    END IF;

    IF v_scope = 'national'
       AND (
            (p_patch ? 'origin_place' AND p_patch->'origin_place'->>'countryCode' <> 'MX')
            OR (p_patch ? 'destination_place' AND p_patch->'destination_place'->>'countryCode' <> 'MX')
       ) THEN
        RETURN jsonb_build_object('error', 'invalid_national_country');
    END IF;

    v_new_customer_id := CASE
        WHEN p_patch ? 'customer_id' THEN NULLIF(p_patch->>'customer_id', '')::uuid
        ELSE v_operation.customer_id
    END;

    IF (p_patch ? 'customer_id') AND v_new_customer_id IS NOT NULL THEN
        SELECT * INTO v_customer
        FROM public.customers
        WHERE id = v_new_customer_id
          AND tenant_id = v_operation.tenant_id;

        IF v_customer.id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_customer');
        END IF;

        IF v_new_customer_id IS DISTINCT FROM v_operation.customer_id AND v_customer.is_active = false THEN
            RETURN jsonb_build_object('error', 'customer_inactive');
        END IF;
    END IF;

    UPDATE public.operations
    SET customer_id = v_new_customer_id,
        client_display_name = CASE
            WHEN p_patch ? 'client_display_name'
                THEN COALESCE(NULLIF(trim(p_patch->>'client_display_name'), ''), client_display_name)
            WHEN (p_patch ? 'customer_id') AND v_customer.id IS NOT NULL
                THEN v_customer.display_name
            ELSE client_display_name
        END,
        operation_scope = v_scope,
        execution_type = v_execution_type,
        service_type = CASE WHEN p_patch ? 'service_type' THEN NULLIF(trim(p_patch->>'service_type'), '') ELSE service_type END,
        origin_place = CASE WHEN p_patch ? 'origin_place' THEN p_patch->'origin_place' ELSE origin_place END,
        destination_place = CASE WHEN p_patch ? 'destination_place' THEN p_patch->'destination_place' ELSE destination_place END,
        destination_city = CASE WHEN p_patch ? 'destination_city' THEN NULLIF(trim(p_patch->>'destination_city'), '') ELSE destination_city END,
        operational_window_start = CASE WHEN p_patch ? 'operational_window_start' THEN NULLIF(p_patch->>'operational_window_start', '')::timestamptz ELSE operational_window_start END,
        operational_window_end = CASE WHEN p_patch ? 'operational_window_end' THEN NULLIF(p_patch->>'operational_window_end', '')::timestamptz ELSE operational_window_end END,
        notes = CASE WHEN p_patch ? 'notes' THEN NULLIF(p_patch->>'notes', '') ELSE notes END,
        cargo_summary = CASE WHEN p_patch ? 'cargo_summary' THEN p_patch->'cargo_summary' ELSE cargo_summary END,
        route_summary = CASE WHEN p_patch ? 'route_summary' THEN NULLIF(trim(p_patch->>'route_summary'), '') ELSE route_summary END,
        provider_cost_amount = CASE WHEN p_patch ? 'provider_cost_amount' THEN NULLIF(p_patch->>'provider_cost_amount', '')::numeric ELSE provider_cost_amount END,
        customer_price_amount = CASE WHEN p_patch ? 'customer_price_amount' THEN NULLIF(p_patch->>'customer_price_amount', '')::numeric ELSE customer_price_amount END,
        pricing_currency = CASE WHEN p_patch ? 'pricing_currency' THEN COALESCE(NULLIF(trim(p_patch->>'pricing_currency'), ''), 'MXN') ELSE pricing_currency END,
        updated_at = now()
    WHERE id = p_operation_id;

    PERFORM public.rpc_write_audit(
        v_operation.tenant_id,
        'update_operation_details',
        'operation',
        p_operation_id,
        jsonb_build_object('patch', p_patch)
    );

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_update_pedimento(uuid, jsonb).definition:
CREATE OR REPLACE FUNCTION public.rpc_update_pedimento(p_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    cur_tenant_id uuid;
    cur_status text;
    new_status text;
BEGIN
    SELECT tenant_id, status INTO cur_tenant_id, cur_status FROM customs_pedimentos WHERE id = p_id;
    IF cur_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'not_found');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = cur_tenant_id
          AND m.role IN ('admin', 'operator')
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    IF p_patch ? 'status' THEN
        new_status := p_patch->>'status';
        -- Very basic transition restrictions (e.g., draft -> validating -> released)
        IF cur_status = 'draft' AND new_status NOT IN ('validating', 'closed', 'blocked') THEN
             RETURN jsonb_build_object('error', 'invalid status transition from draft');
        END IF;
        IF cur_status = 'closed' THEN
             RETURN jsonb_build_object('error', 'cannot update status of closed pedimento');
        END IF;
        
        UPDATE customs_pedimentos SET status = new_status, updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'fecha_pago' THEN
        UPDATE customs_pedimentos SET fecha_pago = (p_patch->>'fecha_pago')::timestamptz, updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'fecha_entrada' THEN
        UPDATE customs_pedimentos SET fecha_entrada = (p_patch->>'fecha_entrada')::timestamptz, updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'fecha_salida' THEN
        UPDATE customs_pedimentos SET fecha_salida = (p_patch->>'fecha_salida')::timestamptz, updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'aduana' THEN
        UPDATE customs_pedimentos SET aduana = p_patch->>'aduana', updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'regimen' THEN
        UPDATE customs_pedimentos SET regimen = p_patch->>'regimen', updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'total_value' THEN
        UPDATE customs_pedimentos SET total_value = (p_patch->>'total_value')::numeric, updated_at = now() WHERE id = p_id;
    END IF;

    IF p_patch ? 'currency' THEN
        UPDATE customs_pedimentos SET currency = p_patch->>'currency', updated_at = now() WHERE id = p_id;
    END IF;

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', SQLERRM);
END;
$function$

public.rpc_update_tenant_settings(uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_update_tenant_settings(p_tenant_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = auth.uid() AND m.tenant_id = p_tenant_id AND m.role IN ('admin', 'operator')) THEN
        RETURN jsonb_build_object('error', 'unauthorized');
    END IF;

    UPDATE tenant_settings SET
        brand_name = COALESCE(p_payload->>'brand_name', brand_name),
        primary_color = COALESCE(p_payload->>'primary_color', primary_color),
        timezone = COALESCE(p_payload->>'timezone', timezone),
        updated_at = now()
    WHERE tenant_id = p_tenant_id;

    PERFORM rpc_write_audit(p_tenant_id, 'update_settings', 'tenant_settings', p_tenant_id, p_payload);

    RETURN jsonb_build_object('success', true);
END;
$function$

public.rpc_validate_module_access(uuid,.definition:
CREATE OR REPLACE FUNCTION public.rpc_validate_module_access(p_tenant_id uuid, p_module_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_is_configured boolean;
    v_config_data jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM memberships m
        WHERE m.user_id = auth.uid()
          AND m.tenant_id = p_tenant_id
    ) THEN
        RETURN jsonb_build_object('error', 'unauthorized', 'is_configured', false);
    END IF;

    SELECT is_configured, config_data INTO v_is_configured, v_config_data
    FROM tenant_setup_status
    WHERE tenant_id = p_tenant_id AND module_name = p_module_name;

    IF v_is_configured IS NULL THEN
        RETURN jsonb_build_object('is_configured', false, 'config_data', '{}'::jsonb);
    END IF;

    RETURN jsonb_build_object('is_configured', v_is_configured, 'config_data', v_config_data);
END;
$function$

public.tanda1_touch_updated_at().definition:
CREATE OR REPLACE FUNCTION public.tanda1_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$function$
